INSERT INTO specialties (prefecture, season, name, description, local_dish, image_url) VALUES
('ibaraki', 'spring', '水戸納豆', '茨城県水戸市を代表する発酵食品。小粒大豆ならではの強い粘りと濃厚な旨みが特徴で、全国的な知名度を誇ります。ご飯にかけるほか、郷土料理にも広く使われます。', '', 'images/ibaraki_mitonatto.png'),
('ibaraki', 'spring', '春キャベツ', '茨城は全国有数のキャベツ産地。春採りは葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/ibaraki_harukyabetsu.png'),
('ibaraki', 'spring', 'しらす', '太平洋に面した茨城沿岸で水揚げされるイワシの稚魚。春は身が柔らかく、釜揚げや生しらすとして味わえます。ご飯や酢の物に合う春の海の幸です。', '', 'images/ibaraki_shirasu.png'),
('ibaraki', 'spring', 'たけのこ', '茨城の里山で春先に掘り出される旬の味覚。えぐみが少なく、シャキッとした歯ざわりが魅力です。煮物や炊き込みご飯、天ぷらで春を感じられます。', '', 'images/ibaraki_takenoko.png'),
('ibaraki', 'spring', '菜の花', '早春の畑を黄色く彩る茨城の春野菜。ほろ苦さと独特の香りが特徴で、おひたしや辛子和えにすると季節感が引き立ちます。栄養価も高い緑黄色野菜です。', '', 'images/ibaraki_nanohana.png'),
('ibaraki', 'spring', 'ハマグリ', '茨城の砂浜で春に旬を迎える二枚貝。ふっくらとした身と上品な出汁の旨みが格別です。お吸い物や酒蒸し、焼きハマグリで磯の香りを堪能できます。', '', 'images/ibaraki_hamaguri.png'),
('ibaraki', 'spring', 'いちご', '茨城は生産量上位を争ういちご王国。春先に最も甘みがのり、果汁たっぷりの大粒が出回ります。そのまま食べるほか、スイーツの材料としても人気です。', '', 'images/ibaraki_ichigo.png'),
('ibaraki', 'spring', 'わかさぎ', '茨城の湖沼で春に多く獲れる小魚。骨までやわらかく、淡白で上品な味わいです。天ぷらや唐揚げ、南蛮漬けにすると丸ごとおいしくいただけます。', '', 'images/ibaraki_wakasagi.png'),
('ibaraki', 'spring', '春レタス', '気候の穏やかな茨城で春に旬を迎えるレタス。葉が瑞々しくパリッとした食感で、ほのかな甘みがあります。サラダはもちろん炒め物でも美味です。', '', 'images/ibaraki_haruretasu.png'),
('ibaraki', 'spring', '新玉ねぎ', '春に収穫される茨城産の早採り玉ねぎ。水分が多く辛みが穏やかで、生でも甘く食べられます。スライスサラダや丸ごと蒸し料理で旬を楽しめます。', '', 'images/ibaraki_shintamanegi.png'),
('ibaraki', 'spring', '山菜', '茨城北部の山あいで春に芽吹く天然の味覚。独特のほろ苦さと香りが春の訪れを告げます。天ぷらやおひたしにして季節限定の風味を味わえます。', '', 'images/ibaraki_sansai.png'),
('ibaraki', 'spring', 'セリ', '水辺に自生する茨城の春の香味野菜。すっきりとした香りとシャキシャキの食感が持ち味です。おひたしや鍋の彩りに加えると爽やかな風味が広がります。', '', 'images/ibaraki_seri.png'),
('ibaraki', 'spring', 'アスパラガス', '茨城は露地アスパラの主要産地。春採りは甘みと瑞々しさが際立ち、太く柔らかい穂先が魅力です。さっと茹でるかソテーで素材の味を活かせます。', '', 'images/ibaraki_asuparagasu.png'),
('ibaraki', 'spring', '春大根', 'やわらかな春に育つ茨城産の大根。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/ibaraki_harudaikon.png'),
('ibaraki', 'spring', 'イワシ', '茨城沿岸で春に脂がのるイワシ。青魚特有の旨みと栄養が豊富です。塩焼きや煮付け、つみれにして、新鮮なうちに味わいたい春の魚です。', '', 'images/ibaraki_iwashi.png'),
('ibaraki', 'spring', '鯛', '茨城の海で春に旬を迎える白身魚の代表格。「桜鯛」と呼ばれ、上品な甘みと締まった身が珍重されます。刺身や塩焼き、鯛めしで祝いの席にも映えます。', '', 'images/ibaraki_tai.png'),
('ibaraki', 'spring', 'よもぎ餅', '春に摘んだよもぎを練り込んだ茨城の郷土菓子。草の爽やかな香りと餅の柔らかさが調和します。あんことの相性も良く、春の行事に欠かせない味です。', '', 'images/ibaraki_yomogimochi.png'),
('ibaraki', 'spring', '梅加工品', '茨城の梅林で収穫される梅を使った保存食。梅干しや梅シロップなど、酸味と塩気のバランスが食欲をそそります。古くから常備される伝統の味です。', '', 'images/ibaraki_umekakouhin.png'),
('ibaraki', 'summer', 'メロン', '茨城は日本一のメロン産地。夏に旬を迎える果実は、とろける果肉とあふれる甘い果汁が自慢です。冷やしてそのまま食べれば極上のデザートになります。', '', 'images/ibaraki_meron.png'),
('ibaraki', 'summer', 'スイカ', '夏の茨城を代表する果物。シャリッとした食感とたっぷりの水分、上品な甘みが暑さを癒します。冷やして頬張る瞬間はまさに夏の風物詩です。', '', 'images/ibaraki_suika.png'),
('ibaraki', 'summer', 'とうもろこし', '茨城の畑で夏に実る甘味野菜。粒がはじけるような食感と強い甘さが特徴で、もぎたては生でも食べられるほど。茹でても焼いても絶品です。', '', 'images/ibaraki_toumorokoshi.png'),
('ibaraki', 'summer', '枝豆', '夏の食卓に欠かせない茨城産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/ibaraki_edamame.png'),
('ibaraki', 'summer', 'ピーマン', '茨城は全国屈指のピーマン産地。夏採りは肉厚で苦みが穏やか、瑞々しい食感です。炒め物や肉詰め、生のサラダで彩りと栄養を添えます。', '', 'images/ibaraki_piiman.png'),
('ibaraki', 'summer', 'トマト', '夏の日差しを浴びて茨城で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製パスタに最適です。', '', 'images/ibaraki_tomato.png'),
('ibaraki', 'summer', 'しじみ', '茨城の汽水域で夏に旬を迎える小ぶりの二枚貝。濃厚な旨みと滋養に富み、味噌汁にすると出汁がよく出ます。夏バテ時の栄養補給にも適しています。', '', 'images/ibaraki_shijimi.png'),
('ibaraki', 'summer', 'アユ', '茨城の清流で夏に育つ川魚。すいかのような爽やかな香りと淡白で繊細な味わいが特徴です。塩焼きにして頭から丸ごと味わうのが王道です。', '', 'images/ibaraki_ayu.png'),
('ibaraki', 'summer', 'ナス', '夏の茨城で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/ibaraki_nasu.png'),
('ibaraki', 'summer', 'きゅうり', '茨城の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/ibaraki_kyuri.png'),
('ibaraki', 'summer', 'ズッキーニ', '夏に茨城で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。ラタトゥイユやソテー、グリルで素材の旨みを引き出せます。', '', 'images/ibaraki_zukkini.png'),
('ibaraki', 'summer', 'ゴーヤ', '夏の茨城で育つ独特の苦みが持ち味の野菜。ビタミン豊富で夏バテ対策に最適です。チャンプルーや天ぷらにすると苦みがやわらぎ食べやすくなります。', '', 'images/ibaraki_goya.png'),
('ibaraki', 'summer', '梨', '茨城は梨の名産地。夏から実る果実は、シャリッとした食感とあふれる果汁、すっきりした甘みが魅力です。冷やして食べれば夏のリフレッシュに最適です。', '秋の「梨」と共通', 'images/ibaraki_nashi.png'),
('ibaraki', 'summer', 'ブルーベリー', '夏に茨城の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。そのまま食べるほかジャムやスイーツにも合います。', '', 'images/ibaraki_buruberi.png'),
('ibaraki', 'summer', 'かぼちゃ', '夏に収穫され茨城で貯蔵されるホクホクの野菜。自然な甘みが濃く、煮物や天ぷら、スープに幅広く使えます。栄養価が高く保存も利く万能野菜です。', '冬の「かぼちゃ」と共通', 'images/ibaraki_kabocha.png'),
('ibaraki', 'summer', 'オクラ', '夏の茨城で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/ibaraki_okura.png'),
('ibaraki', 'summer', '冷やし納豆そば', '茨城名物の納豆を冷たいそばにのせた夏の郷土の味。納豆の粘りとそばの喉ごしが絶妙に絡みます。暑い季節でもさらりと食べられる地元の定番です。', '', 'images/ibaraki_hiyashinattosoba.png'),
('ibaraki', 'summer', '常陸牛焼肉', '茨城が誇るブランド牛・常陸牛を焼肉で味わう一品。きめ細かな霜降りととろける旨みが特徴です。夏のスタミナ補給にぴったりの贅沢なごちそうです。', '', 'images/ibaraki_hitachigyuyakiniku.png'),
('ibaraki', 'autumn', 'れんこん', '茨城は national レベルの蓮根産地。秋に泥の中から掘り出される地下茎で、シャキシャキの食感と粘りが楽しめます。煮物やきんぴら、天ぷらで重宝されます。', '', 'images/ibaraki_renkon.png'),
('ibaraki', 'autumn', '栗', '秋の茨城を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/ibaraki_kuri.png'),
('ibaraki', 'autumn', 'さつまいも', '茨城は干し芋でも有名なさつまいもの名産地。秋に収穫される芋は、しっとり甘くホクホク。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/ibaraki_satsumaimo.png'),
('ibaraki', 'autumn', '梨', '秋に茨城で実る品種の梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として贈答にも喜ばれる果物です。', '夏の「梨」画像を使用', 'images/ibaraki_nashi.png'),
('ibaraki', 'autumn', '新米', '秋に収穫される茨城産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/ibaraki_shinmai.png'),
('ibaraki', 'autumn', '舞茸', '秋に旬を迎える茨城産のきのこ。香り高く歯ごたえがよく、加熱すると豊かな風味が立ちます。天ぷらや炊き込みご飯、鍋で秋の香りを楽しめます。', '', 'images/ibaraki_maitake.png'),
('ibaraki', 'autumn', '常陸秋そば', '茨城が誇る在来種のそば。秋に収穫される実は香りが高く、風味豊かなそばに仕上がります。コシのある食感とそば本来の味わいが評判です。', '', 'images/ibaraki_hitachiakisoba.png'),
('ibaraki', 'autumn', '柿', '秋の茨城で色づく果実。とろりと甘い果肉とやさしい味わいが特徴で、そのまま食べるほか干し柿にも。秋の深まりを感じさせる季節の果物です。', '', 'images/ibaraki_kaki.png'),
('ibaraki', 'autumn', 'しいたけ', '秋に茨城で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/ibaraki_shiitake.png'),
('ibaraki', 'autumn', '里芋', '秋に収穫される茨城産の里芋。ねっとりとした独特の食感とやさしい甘みが持ち味です。煮っころがしや芋煮にすると、ほっとする秋の味わいになります。', '', 'images/ibaraki_satoimo.png'),
('ibaraki', 'autumn', 'ごぼう', '秋に旬を迎える茨城の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。きんぴらや煮物、汁物に加えると料理に滋味深いコクが生まれます。', '', 'images/ibaraki_gobou.png'),
('ibaraki', 'autumn', 'さんま', '秋に茨城沖を回遊する旬の青魚。脂がのって身が締まり、塩焼きにすると香ばしさが格別です。秋の食卓を代表する庶民の魚として親しまれます。', '', 'images/ibaraki_sanma.png'),
('ibaraki', 'autumn', '秋ナス', '秋に茨城で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/ibaraki_akinasu.png'),
('ibaraki', 'autumn', '落花生', '茨城でも栽培される秋の豆。煎ると香ばしく、ほくほくとした食感と濃い旨みが広がります。茹で落花生は産地ならではの旬の味わいです。', '', 'images/ibaraki_rakkasei.png'),
('ibaraki', 'autumn', 'ぶどう', '秋に茨城の果樹園で実るぶどう。みずみずしい果肉と濃厚な甘み、上品な香りが魅力です。粒が大きく食べ応えがあり、秋の果物狩りでも人気です。', '', 'images/ibaraki_budou.png'),
('ibaraki', 'autumn', 'きのこ汁', '秋に採れる複数のきのこを使った茨城の郷土汁。きのこの旨みが溶け出した出汁が体を温めます。山の恵みを存分に味わえる秋ならではの一椀です。', '', 'images/ibaraki_kinokojiru.png'),
('ibaraki', 'autumn', '栗おこわ', '秋の栗をもち米と炊き上げた茨城の行事食。栗のほくほくとした甘みともち米のもちもち感が好相性。実りの秋を祝う席に欠かせない郷土の味です。', '', 'images/ibaraki_kuriokowa.png'),
('ibaraki', 'autumn', '干し芋', '茨城が生産量日本一を誇る秋冬の特産品。さつまいもを蒸して干した自然食品で、凝縮された甘みともっちりした食感が魅力。素朴で滋養豊かな保存食です。', '冬の「ほしいも」と共通', 'images/ibaraki_hoshiimo.png'),
('ibaraki', 'winter', 'あんこう', '茨城の冬を代表する高級魚。コラーゲン豊富でクセのない白身と、濃厚な肝が珍重されます。捨てるところがないと言われ、冬の味覚の王様として名高い魚です。', '', 'images/ibaraki_ankou.png'),
('ibaraki', 'winter', 'ほしいも', '冬に最盛期を迎える茨城特産の干し芋。寒風で干し上げることで甘みが凝縮し、もっちりとした食感に。素朴ながら奥深い、産地自慢の保存食です。', '秋の「干し芋」画像を使用', 'images/ibaraki_hoshiimo.png'),
('ibaraki', 'winter', '白菜', '冬の茨城で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬の食卓に欠かせない万能野菜です。', '', 'images/ibaraki_hakusai.png'),
('ibaraki', 'winter', 'ねぎ', '冬に旬を迎える茨城産のねぎ。加熱するととろりと甘くなり、香りも豊かです。鍋や汁物、薬味として冬の料理に深みと温かみを添えます。', '', 'images/ibaraki_negi.png'),
('ibaraki', 'winter', '常陸牛', '茨城を代表するブランド和牛。きめ細かな霜降りととろけるような旨み、上質な脂が特徴です。すき焼きやステーキで、冬のごちそうとして格別の味わいです。', '', 'images/ibaraki_hitachigyu.png'),
('ibaraki', 'winter', 'ブリ', '冬に脂がのる茨城近海の出世魚。とろりとした濃厚な旨みが冬ならではです。刺身や照り焼き、ぶり大根にすると、寒い季節に身も心も温まります。', '', 'images/ibaraki_buri.png'),
('ibaraki', 'winter', '大根', '冬の茨城で甘みを蓄える根菜。みずみずしくやわらかで、煮るととろける食感に。おでんやぶり大根、漬物に使え、冬の食卓を支える定番野菜です。', '', 'images/ibaraki_daikon.png'),
('ibaraki', 'winter', 'かぼちゃ', '冬至に食べる習慣のある茨城の保存野菜。貯蔵で甘みが増し、ホクホクとした食感が楽しめます。煮物やスープで、栄養豊富な冬の滋養食になります。', '夏の「かぼちゃ」画像を使用', 'images/ibaraki_kabocha.png'),
('ibaraki', 'winter', '小松菜', '冬に旬を迎える茨城産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '', 'images/ibaraki_komatsuna.png'),
('ibaraki', 'winter', 'ほうれん草', '冬に甘みが濃くなる茨城の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/ibaraki_hourensou.png'),
('ibaraki', 'winter', 'あんこう鍋', '茨城の冬を象徴する郷土鍋料理。あんこうの身と肝、野菜を煮込み、濃厚な旨みが溶け出した出汁が絶品です。寒い季節に体の芯から温まる名物です。', '', 'images/ibaraki_ankounabe.png'),
('ibaraki', 'winter', 'けんちん汁', '茨城に伝わる根菜たっぷりの精進汁。大根やごぼう、里芋などを煮込み、優しい味わいが体を温めます。冬の行事や日常に親しまれる郷土の味です。', '', 'images/ibaraki_kenchinjiru.png'),
('ibaraki', 'winter', '干し大根', '冬の寒風で大根を干した茨城の保存食。水分が抜けて甘みと旨みが凝縮します。煮物やはりはり漬けにすると、独特の歯ごたえと風味が楽しめます。', '', 'images/ibaraki_hoshidaikon.png'),
('ibaraki', 'winter', 'わかさぎ唐揚げ', '冬に旬を迎えるわかさぎを揚げた茨城の味。骨まで柔らかく、サクサクの衣と淡白な身が好相性です。湖の恵みを丸ごと味わえる冬の定番料理です。', '', 'images/ibaraki_wakasagikaraage.png'),
('ibaraki', 'winter', '冬キャベツ', '冬の茨城で甘みを増す葉物。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '', 'images/ibaraki_fuyukyabetsu.png'),
('ibaraki', 'winter', '鍋用きのこ', '冬の鍋に欠かせない茨城産のきのこ各種。しいたけや舞茸などの旨みが出汁に溶け、鍋全体の味を深めます。香りと食感で冬の食卓を豊かにします。', '', 'images/ibaraki_nabeyoukinoko.png'),
('ibaraki', 'winter', '納豆汁', '茨城名物の納豆をすりつぶして溶かした郷土汁。とろりとした口当たりと納豆のコク、味噌の風味が体を温めます。寒い冬にぴったりの滋養豊かな一椀です。', '', 'images/ibaraki_nattojiru.png'),
('ibaraki', 'winter', 'レンコン団子', '茨城特産のれんこんをすりおろして作る団子。もちもちとした食感とほのかな甘み、シャキシャキ感が同居します。汁物や揚げ物で楽しむ郷土の味です。', '', 'images/ibaraki_renkondango.png'),
('tochigi', 'spring', 'とちおとめ', '栃木が生んだいちごの代表品種。長年生産量日本一を支える名産で、果汁が多くほどよい酸味と濃い甘みが調和します。春先が最も味がのる旬の果実です。', '', 'images/tochigi_tochiotome.png'),
('tochigi', 'spring', 'スカイベリー', '栃木が開発した大粒の高級いちご。ふっくらと大きく、上品な甘さとジューシーな果肉が特徴です。贈答品としても人気の、県を代表するブランド苺です。', '', 'images/tochigi_skyberry.png'),
('tochigi', 'spring', '山菜', '栃木の山あいで春に芽吹く天然の味覚。ほろ苦さと独特の香りが春の到来を告げます。天ぷらやおひたしにして、季節限定の風味を楽しめます。', '', 'images/tochigi_sansai.png'),
('tochigi', 'spring', 'アスパラガス', '栃木で春に旬を迎える緑黄色野菜。穂先まで柔らかく、甘みと瑞々しさが際立ちます。さっと茹でるかソテーで、春らしい彩りと食感を味わえます。', '', 'images/tochigi_asuparagasu.png'),
('tochigi', 'spring', 'にら', '栃木は全国有数のにら産地。春のにらは葉が柔らかく香り高く、栄養も豊富です。炒め物やにら玉、餃子の具として風味豊かに活躍します。', '', 'images/tochigi_nira.png'),
('tochigi', 'spring', 'たけのこ', '栃木の里山で春に掘られる旬の味覚。えぐみが少なくシャキッとした歯ざわりが魅力です。煮物や天ぷら、炊き込みご飯で春の香りを楽しめます。', '', 'images/tochigi_takenoko.png'),
('tochigi', 'spring', '鮎', '栃木の清流で春から育つ川魚。若鮎は骨まで柔らかく繊細な味わいです。塩焼きや天ぷらにして、清らかな水が育む川の恵みを堪能できます。', '', 'images/tochigi_ayu.png'),
('tochigi', 'spring', '日光湯葉', '日光の名水で作られる栃木の伝統食材。大豆の旨みが凝縮した上品な味わいと、なめらかな口当たりが特徴です。刺身や煮物で精進料理にも使われます。', '', 'images/tochigi_nikkoyuba.png'),
('tochigi', 'spring', '春レタス', '栃木で春に旬を迎えるレタス。葉が瑞々しくパリッとした食感で、ほのかな甘みがあります。サラダや炒め物で、春の爽やかさを味わえます。', '', 'images/tochigi_haruretasu.png'),
('tochigi', 'spring', '春大根', 'やわらかな春に育つ栃木産の大根。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/tochigi_harudaikon.png'),
('tochigi', 'spring', '菜の花', '早春の畑を黄色く彩る栃木の春野菜。ほろ苦さと独特の香りが特徴で、おひたしや辛子和えで季節感が引き立ちます。栄養価の高い緑黄色野菜です。', '', 'images/tochigi_nanohana.png'),
('tochigi', 'spring', 'いちごジャム', 'いちご王国・栃木の苺を煮詰めた加工品。果実の甘酸っぱさをそのまま閉じ込めた濃厚な味わいです。パンやヨーグルトに添えて一年中楽しめます。', '', 'images/tochigi_ichigojam.png'),
('tochigi', 'spring', 'いちご大福', '栃木自慢のいちごを丸ごと包んだ和菓子。みずみずしい苺の酸味とあんこの甘み、餅の柔らかさが見事に調和します。春を感じる人気の銘菓です。', '', 'images/tochigi_ichigodaifuku.png'),
('tochigi', 'spring', '日光ゆば刺し', '日光名物の湯葉を刺身で味わう一品。引き上げたての生湯葉のなめらかさと、大豆の繊細な甘みが堪能できます。わさび醤油でいただく上品な味です。', '', 'images/tochigi_nikkoyubasashi.png'),
('tochigi', 'spring', '春キャベツ', '栃木で春に旬を迎えるキャベツ。葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/tochigi_harukyabetsu.png'),
('tochigi', 'spring', 'わらび', '栃木の山野で春に採れる山菜。独特のぬめりとほろ苦さが特徴で、あく抜きしておひたしや煮物に。春の山の恵みを感じる季節限定の味覚です。', '', 'images/tochigi_warabi.png'),
('tochigi', 'spring', 'こごみ', '春先に栃木の山辺で採れる山菜。クセが少なくほのかなぬめりと甘みがあり、食べやすいのが魅力です。おひたしや天ぷらで春の風味を楽しめます。', '', 'images/tochigi_kogomi.png'),
('tochigi', 'spring', '栃木和牛', '栃木が誇るブランド和牛。きめ細かな霜降りと柔らかな肉質、上品な甘みのある脂が特徴です。すき焼きやステーキで贅沢な味わいを堪能できます。', '秋の「栃木和牛」と共通', 'images/tochigi_tochigiwagyu.png'),
('tochigi', 'summer', 'かんぴょう', '栃木が全国生産の大半を占める特産品。ユウガオの実を細く削って干したもので、独特の歯ごたえと淡白な味わいです。巻き寿司や煮物に欠かせません。', '', 'images/tochigi_kanpyo.png'),
('tochigi', 'summer', 'トマト', '夏の日差しを浴びて栃木で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/tochigi_tomato.png'),
('tochigi', 'summer', 'きゅうり', '栃木の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/tochigi_kyuri.png'),
('tochigi', 'summer', '枝豆', '夏の食卓に欠かせない栃木産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/tochigi_edamame.png'),
('tochigi', 'summer', 'とうもろこし', '栃木の畑で夏に実る甘味野菜。粒がはじけるような食感と強い甘さが特徴で、もぎたては生でも食べられるほど。茹でても焼いても絶品です。', '', 'images/tochigi_toumorokoshi.png'),
('tochigi', 'summer', 'ブルーベリー', '夏に栃木の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。そのまま食べるほかジャムやスイーツにも合います。', '', 'images/tochigi_blueberry.png'),
('tochigi', 'summer', 'ヤシオマス', '栃木が開発したブランドのニジマス。きめ細かな身と上品な脂、臭みのない味わいが特徴です。刺身や塩焼き、ムニエルで清流の恵みを楽しめます。', '', 'images/tochigi_yashiomasu.png'),
('tochigi', 'summer', 'なす', '夏の栃木で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/tochigi_nasu.png'),
('tochigi', 'summer', '冷やし餃子', '餃子の街・宇都宮ならではの夏の食べ方。冷たく締めた餃子はもっちりとした皮と肉汁が引き立ち、さっぱり味わえます。暑い季節に人気の一品です。', '', 'images/tochigi_hiyashigyoza.png'),
('tochigi', 'summer', '鮎の塩焼き', '栃木の清流で育った鮎を塩焼きにした夏の味。すいかのような香りと淡白な身、はらわたのほろ苦さが絶妙です。川魚の旨みを丸ごと堪能できます。', '', 'images/tochigi_ayushioyaki.png'),
('tochigi', 'summer', 'ズッキーニ', '夏に栃木で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。ラタトゥイユやソテー、グリルで素材の旨みを引き出せます。', '', 'images/tochigi_zucchini.png'),
('tochigi', 'summer', 'オクラ', '夏の栃木で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/tochigi_okura.png'),
('tochigi', 'summer', 'モロヘイヤ', '夏に栃木で育つ栄養豊富な葉物野菜。刻むと独特の粘りが出て、青臭さの少ないやさしい味わいです。スープやおひたしで夏の健康野菜として人気です。', '', 'images/tochigi_moroheiya.png'),
('tochigi', 'summer', 'かき氷', '栃木の天然氷で作る夏の風物詩。きめ細かくふんわりと削られた氷は口溶けがよく、頭に響きにくいのが特徴です。涼を求める夏の名物スイーツです。', '', 'images/tochigi_kakigori.png'),
('tochigi', 'summer', '冷やしゆば', '日光名物の湯葉を冷たく仕立てた夏の一品。なめらかな口当たりと大豆の上品な甘みが、暑い季節にさっぱりと味わえます。だしと共に楽しむ涼味です。', '', 'images/tochigi_hiyashiyuba.png'),
('tochigi', 'summer', '夏そば', '夏に新そばが楽しめる栃木のそば。みずみずしい香りとすっきりした喉ごしが特徴で、冷たいざるそばが格別です。暑い季節にぴったりの郷土の味です。', '', 'images/tochigi_natsusoba.png'),
('tochigi', 'summer', 'しそ', '夏に栃木で旬を迎える香味野菜。爽やかな香りと鮮やかな彩りが料理を引き立てます。薬味や天ぷら、ジュースにして夏らしい風味を楽しめます。', '', 'images/tochigi_shiso.png'),
('tochigi', 'summer', '日光天然氷', '厳冬期に切り出し夏まで保存する日光の天然氷。不純物が少なく溶けにくいため、上質なかき氷に使われます。職人技が生む夏の貴重な特産品です。', '', 'images/tochigi_nikkotennenkori.png'),
('tochigi', 'autumn', '梨', '栃木で秋に実る品種の梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として贈答にも喜ばれる果物です。', '', 'images/tochigi_nashi.png'),
('tochigi', 'autumn', 'ぶどう', '秋に栃木の果樹園で実るぶどう。みずみずしい果肉と濃厚な甘み、上品な香りが魅力です。粒が大きく食べ応えがあり、秋の果物狩りでも人気です。', '', 'images/tochigi_budou.png'),
('tochigi', 'autumn', '舞茸', '秋に旬を迎える栃木産のきのこ。香り高く歯ごたえがよく、加熱すると豊かな風味が立ちます。天ぷらや炊き込みご飯、鍋で秋の香りを楽しめます。', '', 'images/tochigi_maitake.png'),
('tochigi', 'autumn', '栃木和牛', '秋にも味わいたい栃木のブランド和牛。霜降りの旨みととろける脂、柔らかな肉質が魅力です。すき焼きやステーキで秋の食欲を満たす贅沢な一品です。', '春の「栃木和牛」画像を使用', 'images/tochigi_tochigiwagyu.png'),
('tochigi', 'autumn', '里芋', '秋に収穫される栃木産の里芋。ねっとりとした独特の食感とやさしい甘みが持ち味です。煮っころがしや芋煮にすると、ほっとする秋の味わいになります。', '', 'images/tochigi_satoimo.png'),
('tochigi', 'autumn', '新そば', '秋に収穫したそばの実で打つ栃木の新そば。香りが高く、みずみずしい風味とコシのある食感が際立ちます。一年で最もそばが旨い季節の味覚です。', '', 'images/tochigi_shinsoba.png'),
('tochigi', 'autumn', 'りんご', '栃木の北部で秋に実るりんご。蜜が入り、甘みと酸味のバランスがよく、シャキッとした食感が魅力です。そのまま食べても加工しても美味です。', '', 'images/tochigi_ringo.png'),
('tochigi', 'autumn', '栗', '秋の栃木を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/tochigi_kuri.png'),
('tochigi', 'autumn', 'しいたけ', '秋に栃木で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/tochigi_shiitake.png'),
('tochigi', 'autumn', 'さつまいも', '秋に収穫される栃木産のさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/tochigi_satsumaimo.png'),
('tochigi', 'autumn', 'かぼちゃ', '秋に旬を迎える栃木のかぼちゃ。自然な甘みが濃く、ホクホクとした食感が楽しめます。煮物や天ぷら、スープに使え、栄養豊富な秋の野菜です。', '', 'images/tochigi_kabocha.png'),
('tochigi', 'autumn', '秋なす', '秋に栃木で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/tochigi_akinasu.png'),
('tochigi', 'autumn', 'きのこ汁', '秋に採れる複数のきのこを使った栃木の郷土汁。きのこの旨みが溶け出した出汁が体を温めます。山の恵みを存分に味わえる秋ならではの一椀です。', '', 'images/tochigi_kinokojiru.png'),
('tochigi', 'autumn', '栗ご飯', '秋の栗を米と炊き上げた栃木の季節料理。栗のほくほくとした甘みとご飯の旨みが調和します。実りの秋を感じさせる、家庭で親しまれる味です。', '', 'images/tochigi_kurigohan.png'),
('tochigi', 'autumn', '新米', '秋に収穫される栃木産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/tochigi_shinmai.png'),
('tochigi', 'autumn', '日光まいたけ', '日光の自然が育む栃木産の舞茸。香りが豊かで歯ごたえがよく、加熱すると旨みが際立ちます。天ぷらや鍋にして、秋の山の恵みを味わえます。', '', 'images/tochigi_nikkomaitake.png'),
('tochigi', 'autumn', 'そば団子', '栃木のそば粉で作る郷土の団子。そばの香ばしい風味ともちもちの食感が特徴です。あんこやみたらしを添えて、秋のおやつや行事食に親しまれます。', '', 'images/tochigi_sobadango.png'),
('tochigi', 'autumn', 'りんごジュース', '栃木産りんごをしぼった秋の加工品。果実の自然な甘みと爽やかな酸味がそのまま味わえます。添加物に頼らない素朴な味わいが人気の特産飲料です。', '', 'images/tochigi_ringojuice.png'),
('tochigi', 'winter', '宇都宮餃子', '餃子の街・宇都宮を代表する冬の名物。野菜たっぷりであっさりとした餡と、パリッと焼き上げた皮が特徴です。冬でも食べたくなる栃木のソウルフードです。', '', 'images/tochigi_utsunomiyagyoza.png'),
('tochigi', 'winter', '大根', '冬の栃木で甘みを蓄える根菜。みずみずしくやわらかで、煮るととろける食感に。おでんや煮物、漬物に使え、冬の食卓を支える定番野菜です。', '', 'images/tochigi_daikon.png'),
('tochigi', 'winter', '白菜', '冬の栃木で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/tochigi_hakusai.png'),
('tochigi', 'winter', 'ねぎ', '冬に旬を迎える栃木産のねぎ。加熱するととろりと甘くなり、香りも豊かです。鍋や汁物、薬味として冬の料理に深みと温かみを添えます。', '', 'images/tochigi_negi.png'),
('tochigi', 'winter', 'いちご', '冬から春にかけて旬を迎える栃木の苺。クリスマスシーズンに出回り始め、甘酸っぱくジューシーな味わいです。いちご王国を象徴する冬の果実です。', '', 'images/tochigi_ichigo.png'),
('tochigi', 'winter', 'ゆば鍋', '日光の湯葉を主役にした栃木の鍋料理。なめらかな湯葉と野菜を煮込み、大豆の旨みが溶け出した出汁が体を温めます。冬の滋養豊かな郷土鍋です。', '', 'images/tochigi_yubanabe.png'),
('tochigi', 'winter', '鹿肉', '栃木の山間部で冬に味わうジビエ。脂肪が少なく高タンパクで、しっかりとした旨みがあります。煮込みや焼き物にすると、野趣あふれる味わいが楽しめます。', '', 'images/tochigi_shikaniku.png'),
('tochigi', 'winter', 'こんにゃく', '栃木で作られる冬の保存食材。独特の弾力ある食感とヘルシーさが魅力です。おでんや煮物、味噌田楽にして、低カロリーで満足感のある一品になります。', '', 'images/tochigi_konnyaku.png'),
('tochigi', 'winter', 'ほうれん草', '冬に甘みが濃くなる栃木の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/tochigi_hourensou.png'),
('tochigi', 'winter', '小松菜', '冬に旬を迎える栃木産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '', 'images/tochigi_komatsuna.png'),
('tochigi', 'winter', 'けんちん汁', '栃木に伝わる根菜たっぷりの精進汁。大根やごぼう、里芋などを煮込み、優しい味わいが体を温めます。冬の行事や日常に親しまれる郷土の味です。', '', 'images/tochigi_kenchinjiru.png'),
('tochigi', 'winter', 'おでん種', '冬の栃木で親しまれるおでんの具材各種。大根やこんにゃく、練り物が出汁を吸い込み、体を芯から温めます。寒い季節の定番として愛される味です。', '', 'images/tochigi_odentane.png'),
('tochigi', 'winter', '栃木和牛すき焼き', '栃木のブランド和牛を堪能するすき焼き。とろける霜降り肉に甘辛い割り下が染み込み、贅沢な旨みが広がります。冬のごちそうとして人気の鍋料理です。', '', 'images/tochigi_tochigiwagyusukiyaki.png'),
('tochigi', 'winter', '冬キャベツ', '冬の栃木で甘みを増す葉物。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '', 'images/tochigi_fuyukyabetsu.png'),
('tochigi', 'winter', '里芋煮', '栃木の里芋を煮込んだ冬の家庭料理。ねっとりとした食感と出汁の染みた優しい味わいが特徴です。体を温める、素朴で滋味深い郷土の味です。', '', 'images/tochigi_satoimoni.png'),
('tochigi', 'winter', '味噌田楽', '栃木で親しまれる冬の郷土料理。こんにゃくや豆腐に甘い味噌だれを塗って焼き上げます。香ばしい味噌の風味と温かさが、寒い季節にぴったりです。', '', 'images/tochigi_misodengaku.png'),
('tochigi', 'winter', '日光湯豆腐', '日光の名水で作る冬の湯豆腐。なめらかな豆腐と湯葉を温かい出汁で味わう、体に優しい一品です。大豆本来の甘みが引き立つ、上品な郷土の味です。', '', 'images/tochigi_nikkoyudofu.png'),
('tochigi', 'winter', '鍋用きのこ', '冬の鍋に欠かせない栃木産のきのこ各種。しいたけや舞茸などの旨みが出汁に溶け、鍋全体の味を深めます。香りと食感で冬の食卓を豊かにします。', '', 'images/tochigi_nabeyoukinoko.png'),
('gunma', 'spring', '山菜', '群馬の山あいで春に芽吹く天然の味覚。ほろ苦さと独特の香りが春の到来を告げます。天ぷらやおひたしにして、季節限定の風味を楽しめます。', '', 'images/gunma_sansai.png'),
('gunma', 'spring', 'いちご', '群馬で春に旬を迎える苺。果汁が多く、ほどよい酸味と甘みのバランスが魅力です。そのまま食べるほか、スイーツの材料としても親しまれています。', '', 'images/gunma_ichigo.png'),
('gunma', 'spring', '春キャベツ', '群馬は全国有数のキャベツ産地。春採りは葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/gunma_harukyabetsu.png'),
('gunma', 'spring', 'うど', '群馬の山辺で春に育つ香味野菜。シャキシャキとした食感と独特の香り、ほのかな苦みが特徴です。酢の物や天ぷら、きんぴらで春の風味を味わえます。', '', 'images/gunma_udo.png'),
('gunma', 'spring', 'わらび', '群馬の山野で春に採れる山菜。独特のぬめりとほろ苦さが特徴で、あく抜きしておひたしや煮物に。春の山の恵みを感じる季節限定の味覚です。', '', 'images/gunma_warabi.png'),
('gunma', 'spring', 'アスパラガス', '群馬で春に旬を迎える緑黄色野菜。穂先まで柔らかく、甘みと瑞々しさが際立ちます。さっと茹でるかソテーで、春らしい彩りと食感を味わえます。', '', 'images/gunma_asuparagasu.png'),
('gunma', 'spring', '川魚', '群馬の清流で春に獲れる川の幸。淡白で繊細な味わいが特徴です。塩焼きや甘露煮にして、山に囲まれた群馬ならではの川魚の旨みを堪能できます。', '', 'images/gunma_kawazana.png'),
('gunma', 'spring', 'こんにゃく', '群馬は全国生産の大半を占めるこんにゃくの本場。弾力ある食感とヘルシーさが魅力です。刺身や田楽、煮物にして、産地ならではの風味を味わえます。', '冬の「こんにゃく」と共通', 'images/gunma_konnyakuimo.png'),
('gunma', 'spring', 'こごみ', '春先に群馬の山辺で採れる山菜。クセが少なくほのかなぬめりと甘みがあり、食べやすいのが魅力です。おひたしや天ぷらで春の風味を楽しめます。', '', 'images/gunma_kogomi.png'),
('gunma', 'spring', '春レタス', '群馬で春に旬を迎えるレタス。葉が瑞々しくパリッとした食感で、ほのかな甘みがあります。サラダや炒め物で、春の爽やかさを味わえます。', '夏の「高原レタス」と共通', 'images/gunma_retasu.png'),
('gunma', 'spring', '菜の花', '早春の畑を黄色く彩る群馬の春野菜。ほろ苦さと独特の香りが特徴で、おひたしや辛子和えで季節感が引き立ちます。栄養価の高い緑黄色野菜です。', '', 'images/gunma_nanohana.png'),
('gunma', 'spring', 'ふきのとう', '早春に群馬の地面から顔を出す山菜。独特のほろ苦さと爽やかな香りが、春の訪れを告げます。天ぷらやふき味噌にして、ほろ苦さを楽しめます。', '', 'images/gunma_fukinotou.png'),
('gunma', 'spring', '梅加工品', '群馬の梅を使った春の保存食。梅干しや梅シロップなど、酸味と塩気のバランスが食欲をそそります。古くから常備される伝統の味わいです。', '', 'images/gunma_umekakouhin.png'),
('gunma', 'spring', '春まいたけ', '群馬で春に出回る栽培舞茸。香り高く歯ごたえがよく、加熱すると豊かな風味が立ちます。天ぷらや炊き込みご飯にして、春の味覚を楽しめます。', '既存の舞茸画像を使用', 'images/gunma_maitake.png'),
('gunma', 'spring', '上州麦豚', '群馬のブランド豚。麦を加えた飼料で育てられ、甘くあっさりとした脂と柔らかな肉質が特徴です。しゃぶしゃぶや生姜焼きで上品な旨みを味わえます。', '', 'images/gunma_joshumugibuta.png'),
('gunma', 'spring', '温泉まんじゅう', '温泉地が多い群馬の名物菓子。茶色い皮の中にこしあんを包んだ素朴な蒸しまんじゅうです。温泉巡りの土産として親しまれる、群馬を代表する銘菓です。', '', 'images/gunma_onsenmanju.png'),
('gunma', 'spring', '新玉ねぎ', '春に収穫される群馬産の早採り玉ねぎ。水分が多く辛みが穏やかで、生でも甘く食べられます。スライスサラダや丸ごと蒸し料理で旬を楽しめます。', '', 'images/gunma_shintamanegi.png'),
('gunma', 'spring', '春大根', 'やわらかな春に育つ群馬産の大根。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/gunma_harudaikon.png'),
('gunma', 'summer', '高原レタス', '群馬の冷涼な高原で育つ夏のレタス。標高を生かした栽培でシャキシャキと瑞々しく、甘みがあります。暑い時期にも安定して出回る群馬自慢の野菜です。', '春のレタス画像を使用', 'images/gunma_retasu.png'),
('gunma', 'summer', '枝豆', '夏の食卓に欠かせない群馬産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/gunma_edamame.png'),
('gunma', 'summer', 'とうもろこし', '群馬の高原で夏に実る甘味野菜。冷涼な気候が糖度を高め、もぎたては生でも食べられるほどの甘さです。茹でても焼いても絶品の夏の味覚です。', '', 'images/gunma_toumorokoshi.png'),
('gunma', 'summer', 'トマト', '夏の日差しを浴びて群馬で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/gunma_tomato.png'),
('gunma', 'summer', 'きゅうり', '群馬の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/gunma_kyuri.png'),
('gunma', 'summer', '桃', '群馬で夏に実る果物。とろけるような果肉とあふれる甘い果汁、上品な香りが魅力です。冷やしてそのまま食べれば、夏の贅沢なデザートになります。', '', 'images/gunma_momo.png'),
('gunma', 'summer', '鮎', '群馬の清流で夏に育つ川魚。すいかのような爽やかな香りと淡白で繊細な味わいが特徴です。塩焼きにして頭から丸ごと味わうのが王道です。', '', 'images/gunma_ayu.png'),
('gunma', 'summer', '水沢うどん', '群馬・伊香保の水沢を発祥とする名物うどん。コシが強く、つるりとした喉ごしと透明感のある麺が特徴です。冷たいざるで食べると夏に格別です。', '', 'images/gunma_mizusawaudon.png'),
('gunma', 'summer', 'ブルーベリー', '夏に群馬の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。そのまま食べるほかジャムやスイーツにも合います。', '', 'images/gunma_blueberry.png'),
('gunma', 'summer', 'ズッキーニ', '夏に群馬で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。ラタトゥイユやソテー、グリルで素材の旨みを引き出せます。', '', 'images/gunma_zucchini.png'),
('gunma', 'summer', 'なす', '夏の群馬で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/gunma_nasu.png'),
('gunma', 'summer', 'オクラ', '夏の群馬で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/gunma_okura.png'),
('gunma', 'summer', 'モロヘイヤ', '夏に群馬で育つ栄養豊富な葉物野菜。刻むと独特の粘りが出て、青臭さの少ないやさしい味わいです。スープやおひたしで夏の健康野菜として人気です。', '', 'images/gunma_moroheiya.png'),
('gunma', 'summer', '夏キャベツ', '群馬の高原で夏に収穫されるキャベツ。冷涼な気候で育ち、瑞々しく甘みがあります。暑い時期でもみずみずしさを保つ、群馬を代表する夏野菜です。', '', 'images/gunma_natsukyabetsu.png'),
('gunma', 'summer', '冷やしうどん', '群馬の小麦で打つうどんを冷たく仕立てた夏の味。コシのある麺とつるりとした喉ごしが、暑い季節にぴったりです。粉どころ群馬らしい郷土の味です。', '', 'images/gunma_hiyashiudon.png'),
('gunma', 'summer', '焼きとうもろこし', '群馬の高原とうもろこしを香ばしく焼いた夏の味。醤油の香りと甘い実が食欲をそそります。夏祭りや行楽でも親しまれる、季節を感じる一品です。', '', 'images/gunma_yakitoumorokoshi.png'),
('gunma', 'summer', '高原野菜', '群馬の冷涼な高原で育つ夏野菜の総称。レタスやキャベツなどが瑞々しく甘く育ちます。標高を生かした栽培が生む、夏でも新鮮な群馬自慢の野菜です。', '', 'images/gunma_kougenyasai.png'),
('gunma', 'summer', 'こんにゃく冷麺', '群馬名産のこんにゃくを麺状にした夏の一品。低カロリーでつるりとした喉ごしが、暑い季節にさっぱり味わえます。ヘルシー志向にも嬉しい郷土の味です。', '', 'images/gunma_konnyakureimen.png'),
('gunma', 'autumn', 'まいたけ', '秋に旬を迎える群馬産のきのこ。香り高く歯ごたえがよく、加熱すると豊かな風味が立ちます。天ぷらや炊き込みご飯、鍋で秋の香りを楽しめます。', '', 'images/gunma_maitake.png'),
('gunma', 'autumn', 'りんご', '群馬の山間で秋に実るりんご。蜜が入り、甘みと酸味のバランスがよく、シャキッとした食感が魅力です。そのまま食べても加工しても美味です。', '', 'images/gunma_ringo.png'),
('gunma', 'autumn', '下仁田ねぎ', '群馬・下仁田の特産ねぎ。太く短い見た目が特徴で、生では辛いが加熱すると驚くほど甘くとろけます。すき焼きや鍋で真価を発揮する高級ねぎです。', '冬の「下仁田ねぎ」と共通', 'images/gunma_shimonitanegi.png'),
('gunma', 'autumn', '焼きまんじゅう', '群馬を代表する郷土菓子。串に刺した素まんじゅうに甘い味噌だれを塗って焼き上げます。香ばしい味噌の香りともちもち食感が、秋の行楽にぴったりです。', '', 'images/gunma_yakimanju.png'),
('gunma', 'autumn', '舞茸鍋', '秋の群馬産舞茸を主役にした鍋料理。きのこの豊かな香りと旨みが出汁に溶け出し、滋味深い味わいに。山の恵みを存分に味わえる秋の郷土鍋です。', '', 'images/gunma_maitakenabe.png'),
('gunma', 'autumn', '栗', '秋の群馬を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/gunma_kuri.png'),
('gunma', 'autumn', 'さつまいも', '秋に収穫される群馬産のさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/gunma_satsumaimo.png'),
('gunma', 'autumn', '梨', '群馬で秋に実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として贈答にも喜ばれる果物です。', '', 'images/gunma_nashi.png'),
('gunma', 'autumn', 'しいたけ', '秋に群馬で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/gunma_shiitake.png'),
('gunma', 'autumn', '新米', '秋に収穫される群馬産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/gunma_shinmai.png'),
('gunma', 'autumn', '山ぶどう', '群馬の山野で秋に実る野生種のぶどう。小粒ながら濃厚な甘酸っぱさと豊かな香りが特徴です。そのまま食べるほかジュースやジャムにして楽しめます。', '', 'images/gunma_yamabudou.png'),
('gunma', 'autumn', '秋なす', '秋に群馬で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/gunma_akinasu.png'),
('gunma', 'autumn', 'きのこ汁', '秋に採れる複数のきのこを使った群馬の郷土汁。きのこの旨みが溶け出した出汁が体を温めます。山の恵みを存分に味わえる秋ならではの一椀です。', '', 'images/gunma_kinokojiru.png'),
('gunma', 'autumn', 'こんにゃく味噌田楽', '群馬名産のこんにゃくに味噌だれを塗った郷土料理。弾力ある食感と甘い味噌の香りが好相性です。産地ならではのこんにゃくを堪能できる秋の味です。', '', 'images/gunma_konnyakumiso_dengaku.png'),
('gunma', 'autumn', '上州牛', '群馬を代表するブランド和牛。きめ細かな霜降りと柔らかな肉質、上品な旨みが特徴です。すき焼きやステーキで、秋の食欲を満たす贅沢な味わいです。', '冬の「上州牛」と共通', 'images/gunma_joshugyu.png'),
('gunma', 'autumn', '里芋', '秋に収穫される群馬産の里芋。ねっとりとした独特の食感とやさしい甘みが持ち味です。煮っころがしや芋煮にすると、ほっとする秋の味わいになります。', '', 'images/gunma_satoimo.png'),
('gunma', 'autumn', 'ごぼう', '秋に旬を迎える群馬の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。きんぴらや煮物、汁物に加えると料理に滋味深いコクが生まれます。', '', 'images/gunma_gobou.png'),
('gunma', 'autumn', '秋キャベツ', '秋に群馬で収穫されるキャベツ。夏より葉が締まり、甘みとコクが増します。炒め物や煮込み、鍋にして、秋らしいしっかりした味わいを楽しめます。', '', 'images/gunma_akikyabetsu.png'),
('gunma', 'winter', '下仁田ねぎ', '群馬・下仁田が誇る冬の高級ねぎ。寒さで甘みが極まり、加熱すると驚くほどとろりと甘くなります。すき焼きや鍋でこそ真価を発揮する冬の名産です。', '既存の下仁田ねぎ画像を使用', 'images/gunma_shimonitanegi.png'),
('gunma', 'winter', 'こんにゃく', '群馬で冬に親しまれる本場のこんにゃく。弾力ある食感とヘルシーさが魅力で、味が染みやすいのが特徴です。おでんや煮物で体を温める冬の定番です。', '既存のこんにゃく画像を使用', 'images/gunma_konnyakuimo.png'),
('gunma', 'winter', 'やまといも', '群馬で冬に旬を迎える粘りの強い山芋。すりおろすと濃厚なとろろになり、独特のコクが楽しめます。とろろご飯や汁物で滋養豊かに味わえます。', '', 'images/gunma_yamatoimo.png'),
('gunma', 'winter', '上州牛', '群馬の冬に味わいたいブランド和牛。霜降りの旨みととろける脂、柔らかな肉質が魅力です。すき焼きや鍋で、寒い季節のごちそうとして格別です。', '秋の「上州牛」画像を使用', 'images/gunma_joshugyu.png'),
('gunma', 'winter', '白菜', '冬の群馬で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/gunma_hakusai.png'),
('gunma', 'winter', 'みそおでん', '群馬で親しまれる味噌仕立てのおでん。こんにゃくや大根に甘い味噌だれが染み込み、体を温めます。寒い季節にうれしい、産地らしい郷土の味です。', '', 'images/gunma_misooden.png'),
('gunma', 'winter', '大根', '冬の群馬で甘みを蓄える根菜。みずみずしくやわらかで、煮るととろける食感に。おでんや煮物、漬物に使え、冬の食卓を支える定番野菜です。', '', 'images/gunma_daikon.png'),
('gunma', 'winter', '鍋料理', '寒い群馬の冬に欠かせない郷土の鍋。下仁田ねぎや上州牛、こんにゃくなど地元の食材が出汁に旨みを溶かします。体を芯から温める冬のごちそうです。', '', 'images/gunma_nabelyouri.png'),
('gunma', 'winter', 'ほうれん草', '冬に甘みが濃くなる群馬の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/gunma_hourensou.png'),
('gunma', 'winter', '小松菜', '冬に旬を迎える群馬産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '', 'images/gunma_komatsuna.png'),
('gunma', 'winter', 'ねぎ鍋', '群馬の下仁田ねぎを主役にした冬の鍋。とろりと甘くなったねぎの旨みが出汁に溶け出します。ねぎの産地ならではの、シンプルで滋味深い郷土鍋です。', '', 'images/gunma_neginabe.png'),
('gunma', 'winter', 'すき焼き', '上州牛と下仁田ねぎを使う群馬のすき焼き。とろける霜降り肉に甘辛い割り下と甘いねぎが絡みます。地元の名産が揃う、冬のごちそうの代表格です。', '', 'images/gunma_sukiyaki.png'),
('gunma', 'winter', 'けんちん汁', '群馬に伝わる根菜たっぷりの精進汁。大根やごぼう、里芋などを煮込み、優しい味わいが体を温めます。冬の行事や日常に親しまれる郷土の味です。', '', 'images/gunma_kenchinjiru.png'),
('gunma', 'winter', '冬キャベツ', '冬の群馬で甘みを増す葉物。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '', 'images/gunma_fuyukyabetsu.png'),
('gunma', 'winter', '上州麦豚鍋', '群馬のブランド豚・上州麦豚を使った冬の鍋。甘くあっさりした脂と柔らかな肉が、野菜とともに出汁に旨みを添えます。寒い季節に人気の郷土鍋です。', '', 'images/gunma_joshumugibutanabe.png'),
('gunma', 'winter', '湯豆腐', '群馬の冬に親しまれる温かい豆腐料理。なめらかな豆腐を出汁で温め、大豆本来の甘みを味わいます。体に優しく、寒い夜にほっとする一品です。', '', 'images/gunma_yudofu.png'),
('gunma', 'winter', 'こんにゃく田楽', '群馬名産のこんにゃくに味噌だれを塗って焼く冬の郷土料理。香ばしい味噌と弾力ある食感が好相性です。産地ならではのこんにゃくを温かく味わえます。', '', 'images/gunma_konnyakudengaku.png'),
('gunma', 'winter', '鍋用きのこ', '冬の鍋に欠かせない群馬産のきのこ各種。しいたけや舞茸などの旨みが出汁に溶け、鍋全体の味を深めます。香りと食感で冬の食卓を豊かにします。', '', 'images/gunma_nabeyoukinoko.png'),
('saitama', 'spring', '狭山茶', '埼玉・狭山地方で育つ日本三大銘茶のひとつ。「狭山火入れ」と呼ばれる仕上げで、濃厚な甘みと深い味わいが生まれます。春の新茶は格別の香りです。', '「狭山新茶」と共通', 'images/saitama_sayamacha.png'),
('saitama', 'spring', 'いちご', '埼玉で春に旬を迎える苺。果汁が多くほどよい酸味と甘みのバランスが魅力です。観光農園での摘み取りも人気で、そのまま味わうのが一番です。', '', 'images/saitama_ichigo.png'),
('saitama', 'spring', '小松菜', '埼玉は全国有数の小松菜産地。春採りは葉が柔らかく、アクが少なく食べやすいのが特徴です。おひたしや炒め物、汁物で栄養豊かに楽しめます。', '他の季節の小松菜と共通', 'images/saitama_komatsuna.png'),
('saitama', 'spring', 'たけのこ', '埼玉の里山で春に掘られる旬の味覚。えぐみが少なくシャキッとした歯ざわりが魅力です。煮物や天ぷら、炊き込みご飯で春の香りを楽しめます。', '', 'images/saitama_takenoko.png'),
('saitama', 'spring', '菜の花', '早春の畑を黄色く彩る埼玉の春野菜。ほろ苦さと独特の香りが特徴で、おひたしや辛子和えで季節感が引き立ちます。栄養価の高い緑黄色野菜です。', '', 'images/saitama_nanohana.png'),
('saitama', 'spring', 'うど', '埼玉で春に育つ香味野菜。シャキシャキとした食感と独特の香り、ほのかな苦みが特徴です。酢の物や天ぷら、きんぴらで春の風味を味わえます。', '', 'images/saitama_udo.png'),
('saitama', 'spring', '川越太麺焼きそば', '埼玉・川越に伝わる名物焼きそば。極太の麺にソースがよく絡み、もちもちとした食感が楽しめます。下町情緒あふれる、地元で愛されるソウルフードです。', '', 'images/saitama_kawagoefutomenyakisoba.png'),
('saitama', 'spring', '山菜', '埼玉の山あいで春に芽吹く天然の味覚。ほろ苦さと独特の香りが春の到来を告げます。天ぷらやおひたしにして、季節限定の風味を楽しめます。', '', 'images/saitama_sansai.png'),
('saitama', 'spring', '春キャベツ', '埼玉で春に旬を迎えるキャベツ。葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/saitama_harukyabetsu.png'),
('saitama', 'spring', '春大根', 'やわらかな春に育つ埼玉産の大根。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/saitama_harudaikon.png'),
('saitama', 'spring', '新玉ねぎ', '春に収穫される埼玉産の早採り玉ねぎ。水分が多く辛みが穏やかで、生でも甘く食べられます。スライスサラダや丸ごと蒸し料理で旬を楽しめます。', '', 'images/saitama_shintamanegi.png'),
('saitama', 'spring', 'アスパラガス', '埼玉で春に旬を迎える緑黄色野菜。穂先まで柔らかく、甘みと瑞々しさが際立ちます。さっと茹でるかソテーで、春らしい彩りと食感を味わえます。', '', 'images/saitama_asuparagasu.png'),
('saitama', 'spring', '草加せんべい', '埼玉・草加の名物焼き煎餅。良質な米を使い、職人が一枚一枚堅く焼き上げます。醤油の香ばしさとパリッとした歯ごたえが、長く愛される郷土の味です。', '冬の「草加せんべい」と共通', 'images/saitama_sokasendei.png'),
('saitama', 'spring', '狭山新茶', '春一番に摘まれる狭山茶の新茶。若葉ならではの爽やかな香りとまろやかな甘みが格別です。一年で最も茶葉が旨い、春を告げる埼玉自慢の味です。', '既存の狭山茶画像を使用', 'images/saitama_sayamacha.png'),
('saitama', 'spring', 'いちご大福', '埼玉の苺を丸ごと包んだ和菓子。みずみずしい苺の酸味とあんこの甘み、餅の柔らかさが見事に調和します。春を感じる人気の和菓子です。', '', 'images/saitama_ichigodaifuku.png'),
('saitama', 'spring', '春レタス', '埼玉で春に旬を迎えるレタス。葉が瑞々しくパリッとした食感で、ほのかな甘みがあります。サラダや炒め物で、春の爽やかさを味わえます。', '', 'images/saitama_haruretasu.png'),
('saitama', 'spring', 'わらび', '埼玉の山野で春に採れる山菜。独特のぬめりとほろ苦さが特徴で、あく抜きしておひたしや煮物に。春の山の恵みを感じる季節限定の味覚です。', '', 'images/saitama_warabi.png'),
('saitama', 'spring', '秩父そば', '埼玉・秩父地方の山里で育つそば。冷涼な気候が生む香り高い実で打たれ、コシのある食感が特徴です。澄んだ水と土地が育む、秩父自慢の味です。', '', 'images/saitama_chichibusoba.png'),
('saitama', 'summer', '枝豆', '夏の食卓に欠かせない埼玉産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/saitama_edamame.png'),
('saitama', 'summer', 'きゅうり', '埼玉の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/saitama_kyuri.png'),
('saitama', 'summer', 'トマト', '夏の日差しを浴びて埼玉で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/saitama_tomato.png'),
('saitama', 'summer', 'ブルーベリー', '夏に埼玉の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。そのまま食べるほかジャムやスイーツにも合います。', '', 'images/saitama_blueberry.png'),
('saitama', 'summer', 'とうもろこし', '埼玉の畑で夏に実る甘味野菜。粒がはじけるような食感と強い甘さが特徴で、もぎたては生でも食べられるほど。茹でても焼いても絶品です。', '', 'images/saitama_toumorokoshi.png'),
('saitama', 'summer', '冷汁うどん', '埼玉に伝わる夏の郷土うどん。冷たいごまだれや味噌だれに、コシのある地元のうどんをつけて食べます。暑い季節にさっぱりと食べられる粉どころの味です。', '', 'images/saitama_hiyashijiruudon.png'),
('saitama', 'summer', 'すいか', '夏の埼玉を代表する果物。シャリッとした食感とたっぷりの水分、上品な甘みが暑さを癒します。冷やして頬張る瞬間はまさに夏の風物詩です。', '', 'images/saitama_suika.png'),
('saitama', 'summer', '梨', '埼玉で夏から実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。冷やして食べれば夏のリフレッシュに最適です。', '秋の「梨」と共通', 'images/saitama_nashi.png'),
('saitama', 'summer', 'なす', '夏の埼玉で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/saitama_nasu.png'),
('saitama', 'summer', 'オクラ', '夏の埼玉で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/saitama_okura.png'),
('saitama', 'summer', 'ズッキーニ', '夏に埼玉で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。ラタトゥイユやソテー、グリルで素材の旨みを引き出せます。', '', 'images/saitama_zucchini.png'),
('saitama', 'summer', 'モロヘイヤ', '夏に埼玉で育つ栄養豊富な葉物野菜。刻むと独特の粘りが出て、青臭さの少ないやさしい味わいです。スープやおひたしで夏の健康野菜として人気です。', '', 'images/saitama_moroheiya.png'),
('saitama', 'summer', '冷やし肉汁うどん', '埼玉名物の肉汁うどんを冷たく仕立てた夏の味。コシの強い麺を、豚肉とねぎの温かい肉汁につけて食べます。粉どころ埼玉を代表する夏の定番です。', '', 'images/saitama_hiyashinikujiruudon.png'),
('saitama', 'summer', '夏野菜カレー', '埼玉の夏野菜をたっぷり使ったカレー。なすやトマト、ピーマンなど旬の野菜の旨みが溶け込みます。彩り豊かで栄養満点の、夏にうれしい一皿です。', '', 'images/saitama_natsuyasaicurry.png'),
('saitama', 'summer', 'かき氷', '埼玉・秩父の天然氷で作る夏の風物詩。きめ細かくふんわり削られた氷は口溶けがよく、上質な甘味が楽しめます。涼を求める夏の名物スイーツです。', '', 'images/saitama_kakigori.png'),
('saitama', 'summer', '秩父天然氷', '秩父の厳冬期に切り出される貴重な天然氷。不純物が少なく溶けにくいため、極上のかき氷に使われます。職人技が生む埼玉自慢の夏の特産品です。', '', 'images/saitama_chichibutennenkori.png'),
('saitama', 'summer', '焼きとうもろこし', '埼玉のとうもろこしを香ばしく焼いた夏の味。醤油の香りと甘い実が食欲をそそります。夏祭りや行楽でも親しまれる、季節を感じる一品です。', '', 'images/saitama_yakitoumorokoshi.png'),
('saitama', 'summer', '夏小松菜', '暑い時期にも育つ埼玉産の小松菜。夏採りはシャキッとした食感で、栄養価も高く重宝されます。おひたしや炒め物で、夏でも手軽に青菜を補えます。', '既存の小松菜画像を使用', 'images/saitama_komatsuna.png'),
('saitama', 'autumn', '川越いも', '埼玉・川越を代表するさつまいも。江戸の昔から愛され、ほくほくとした上品な甘みが特徴です。焼き芋や芋菓子にして、秋の味覚を存分に楽しめます。', '既存のさつまいも画像を使用', 'images/saitama_satsumaimo.png'),
('saitama', 'autumn', 'さつまいも', '秋に収穫される埼玉産のさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/saitama_satsumaimo.png'),
('saitama', 'autumn', '深谷ねぎ', '埼玉・深谷の特産ねぎ。きめ細かくやわらかで、加熱すると驚くほど甘くなります。鍋やすき焼き、焼きねぎにして、産地ならではの甘みを味わえます。', '冬の「深谷ねぎ」と共通', 'images/saitama_fukayanegi.png'),
('saitama', 'autumn', '新米', '秋に収穫される埼玉産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/saitama_shinmai.png'),
('saitama', 'autumn', 'ぶどう', '秋に埼玉の果樹園で実るぶどう。みずみずしい果肉と濃厚な甘み、上品な香りが魅力です。粒が大きく食べ応えがあり、秋の果物狩りでも人気です。', '', 'images/saitama_budou.png'),
('saitama', 'autumn', '栗', '秋の埼玉を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/saitama_kuri.png'),
('saitama', 'autumn', '里芋', '秋に収穫される埼玉産の里芋。ねっとりとした独特の食感とやさしい甘みが持ち味です。煮っころがしや芋煮にすると、ほっとする秋の味わいになります。', '', 'images/saitama_satoimo.png'),
('saitama', 'autumn', '豚みそ丼', '埼玉・秩父に伝わる郷土の丼物。味噌だれに漬けた豚肉を香ばしく焼き、ご飯にのせます。甘辛い味噌の風味とご飯の相性が抜群の、秩父名物です。', '', 'images/saitama_butamisodon.png'),
('saitama', 'autumn', '梨', '埼玉で秋に実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として贈答にも喜ばれる果物です。', '夏の「梨」画像を使用', 'images/saitama_nashi.png'),
('saitama', 'autumn', '秋なす', '秋に埼玉で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/saitama_akinasu.png'),
('saitama', 'autumn', 'しいたけ', '秋に埼玉で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/saitama_shiitake.png'),
('saitama', 'autumn', 'きのこ汁', '秋に採れる複数のきのこを使った埼玉の郷土汁。きのこの旨みが溶け出した出汁が体を温めます。山の恵みを存分に味わえる秋ならではの一椀です。', '', 'images/saitama_kinokojiru.png'),
('saitama', 'autumn', '芋ようかん', '埼玉・川越のさつまいもで作る秋の和菓子。芋本来の自然な甘みとしっとりした食感が魅力です。素朴ながら奥深い、芋どころならではの銘菓です。', '', 'images/saitama_imoyokan.png'),
('saitama', 'autumn', '焼き芋', '埼玉の川越いもをじっくり焼き上げた秋の味。皮は香ばしく、中はとろりと甘く仕上がります。芋どころならではの、ほっとする秋のおやつです。', '', 'images/saitama_yakiimo.png'),
('saitama', 'autumn', '秩父きのこ', '埼玉・秩父の山で秋に採れるきのこ各種。香り高く歯ごたえがよく、自然の旨みが凝縮しています。鍋や汁物にして、秩父の山の恵みを味わえます。', '', 'images/saitama_chichibukinoko.png'),
('saitama', 'autumn', 'ごぼう', '秋に旬を迎える埼玉の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。きんぴらや煮物、汁物に加えると料理に滋味深いコクが生まれます。', '', 'images/saitama_gobou.png'),
('saitama', 'autumn', '秋小松菜', '秋に埼玉で旬を迎える小松菜。涼しくなり甘みと栄養が増します。おひたしや炒め物、汁物に使え、秋の食卓に手軽に青菜を添えられます。', '', 'images/saitama_akikomatsuna.png'),
('saitama', 'autumn', '栗ご飯', '秋の栗を米と炊き上げた埼玉の季節料理。栗のほくほくとした甘みとご飯の旨みが調和します。実りの秋を感じさせる、家庭で親しまれる味です。', '', 'images/saitama_kurigohan.png'),
('saitama', 'winter', '深谷ねぎ', '埼玉・深谷が誇る冬の特産ねぎ。寒さで甘みが極まり、加熱するととろりと甘くなります。すき焼きや鍋、焼きねぎで真価を発揮する冬の名産です。', '既存の深谷ねぎ画像を使用', 'images/saitama_fukayanegi.png'),
('saitama', 'winter', '小松菜', '冬に旬を迎える埼玉産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '既存の小松菜画像を使用', 'images/saitama_komatsuna.png'),
('saitama', 'winter', '武州和牛', '埼玉で育てられるブランド和牛。きめ細かな霜降りと柔らかな肉質、上品な旨みが特徴です。すき焼きやステーキで、冬のごちそうとして格別の味わいです。', '', 'images/saitama_bushuwagyu.png'),
('saitama', 'winter', '鍋焼きうどん', '埼玉の小麦で打つうどんを土鍋で煮込む冬の味。コシのある麺に出汁が染み込み、具材とともに体を温めます。粉どころ埼玉らしい冬の定番料理です。', '', 'images/saitama_nabeyakiudon.png'),
('saitama', 'winter', '白菜', '冬の埼玉で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/saitama_hakusai.png'),
('saitama', 'winter', '大根', '冬の埼玉で甘みを蓄える根菜。みずみずしくやわらかで、煮るととろける食感に。おでんや煮物、漬物に使え、冬の食卓を支える定番野菜です。', '', 'images/saitama_daikon.png'),
('saitama', 'winter', 'ほうれん草', '冬に甘みが濃くなる埼玉の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/saitama_hourensou.png'),
('saitama', 'winter', '味噌ポテト', '埼玉・秩父の郷土おやつ。蒸したじゃがいもに衣をつけて揚げ、甘い味噌だれをかけます。ほくほくの芋と甘辛い味噌が好相性の、素朴な冬の味です。', '', 'images/saitama_misopotato.png'),
('saitama', 'winter', 'ねぎ鍋', '埼玉の深谷ねぎを主役にした冬の鍋。とろりと甘くなったねぎの旨みが出汁に溶け出します。ねぎの産地ならではの、シンプルで滋味深い郷土鍋です。', '', 'images/saitama_neginabe.png'),
('saitama', 'winter', 'おっきりこみ', '埼玉北部に伝わる幅広麺の煮込み料理。野菜とともに味噌や醤油で煮込み、とろみのある汁が体を温めます。粉どころの知恵が詰まった冬の郷土食です。', '', 'images/saitama_okkirikomi.png'),
('saitama', 'winter', 'けんちん汁', '埼玉に伝わる根菜たっぷりの精進汁。大根やごぼう、里芋などを煮込み、優しい味わいが体を温めます。冬の行事や日常に親しまれる郷土の味です。', '', 'images/saitama_kenchinjiru.png'),
('saitama', 'winter', '冬キャベツ', '冬の埼玉で甘みを増す葉物。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '', 'images/saitama_fuyukyabetsu.png'),
('saitama', 'winter', '里芋煮', '埼玉の里芋を煮込んだ冬の家庭料理。ねっとりとした食感と出汁の染みた優しい味わいが特徴です。体を温める、素朴で滋味深い郷土の味です。', '', 'images/saitama_satoimoni.png'),
('saitama', 'winter', 'すき焼き', '武州和牛と深谷ねぎを使う埼玉のすき焼き。とろける霜降り肉に甘辛い割り下と甘いねぎが絡みます。地元の名産が揃う、冬のごちそうの代表格です。', '', 'images/saitama_sukiyaki.png'),
('saitama', 'winter', '草加せんべい', '埼玉・草加の名物焼き煎餅。堅く焼き上げた生地の香ばしさとパリッとした歯ごたえが特徴です。冬の温かいお茶と合わせたい、長く愛される郷土の味です。', '春の「草加せんべい」を使用', 'images/saitama_sokasendei.png'),
('saitama', 'winter', '煮ぼうとう', '埼玉・深谷に伝わる幅広麺の煮込み。深谷ねぎなどの野菜とともに醤油で煮込み、とろみのある汁が体を温めます。冬に親しまれる素朴な郷土料理です。', '', 'images/saitama_niboutou.png'),
('saitama', 'winter', '冬小松菜', '冬に旬を迎える埼玉産の小松菜。霜にあたって甘みが増し、葉も肉厚になります。おひたしや鍋の具にして、寒い時期に栄養豊富な青菜を味わえます。', '', 'images/saitama_fuyukomatsuna.png'),
('saitama', 'winter', 'おでん', '寒い埼玉の冬に親しまれる煮込み料理。大根やこんにゃく、練り物が出汁を吸い込み、体を芯から温めます。家庭でも屋台でも愛される冬の定番です。', '', 'images/saitama_oden.png'),
('chiba', 'spring', '房州びわ', '千葉・南房総の特産果物。温暖な気候が育む大粒のびわで、上品な甘みとみずみずしい果肉が魅力です。初夏を告げる、千葉自慢の高級フルーツです。', '', 'images/chiba_biwa.png'),
('chiba', 'spring', 'たけのこ', '千葉の里山で春に掘られる旬の味覚。えぐみが少なくシャキッとした歯ざわりが魅力です。煮物や天ぷら、炊き込みご飯で春の香りを楽しめます。', '', 'images/chiba_takenoko.png'),
('chiba', 'spring', '菜の花', '千葉は菜の花の名産地。早春の畑を黄色く彩り、ほろ苦さと独特の香りが特徴です。おひたしや辛子和えで、千葉ならではの春の味覚を楽しめます。', '', 'images/chiba_nanohana.png'),
('chiba', 'spring', 'アジ', '千葉の海で春に旬を迎える青魚。脂がのって身が締まり、上品な旨みがあります。刺身やなめろう、塩焼きにして、新鮮な海の幸を堪能できます。', '', 'images/chiba_aji.png'),
('chiba', 'spring', 'ハマグリ', '千葉の砂浜で春に旬を迎える二枚貝。ふっくらとした身と上品な出汁の旨みが格別です。お吸い物や酒蒸し、焼きハマグリで磯の香りを堪能できます。', '冬の「はまぐり」と共通', 'images/chiba_hamaguri.png'),
('chiba', 'spring', 'いちご', '千葉で春に旬を迎える苺。果汁が多くほどよい酸味と甘みのバランスが魅力です。観光農園での摘み取りも盛んで、そのまま味わうのが一番です。', '', 'images/chiba_ichigo.png'),
('chiba', 'spring', 'しらす', '千葉の沿岸で水揚げされるイワシの稚魚。春は身が柔らかく、釜揚げや生しらすとして味わえます。ご飯や酢の物に合う春の海の幸です。', '', 'images/chiba_shirasu.png'),
('chiba', 'spring', '鯛', '千葉の海で春に旬を迎える白身魚の代表格。「桜鯛」と呼ばれ、上品な甘みと締まった身が珍重されます。刺身や塩焼き、鯛めしで祝いの席にも映えます。', '', 'images/chiba_tai.png'),
('chiba', 'spring', '春キャベツ', '千葉は全国有数のキャベツ産地。春採りは葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/chiba_harukyabetsu.png'),
('chiba', 'spring', '春大根', '千葉は大根の名産地。春採りはみずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/chiba_harudaikon.png'),
('chiba', 'spring', '新玉ねぎ', '春に収穫される千葉産の早採り玉ねぎ。水分が多く辛みが穏やかで、生でも甘く食べられます。スライスサラダや丸ごと蒸し料理で旬を楽しめます。', '', 'images/chiba_shintamanegi.png'),
('chiba', 'spring', '海苔', '千葉の海で育つ春の海産物。香り高く、口に入れるととろけるような食感です。焼き海苔やおにぎり、巻き寿司にして、磯の風味を存分に味わえます。', '冬の「海苔」と共通', 'images/chiba_nori.png'),
('chiba', 'spring', 'あさり', '千葉の干潟で春に旬を迎える二枚貝。ふっくらとした身と濃厚な出汁の旨みが魅力です。味噌汁や酒蒸し、ボンゴレにして春の磯の味を楽しめます。', '', 'images/chiba_asari.png'),
('chiba', 'spring', 'サザエ', '千葉の磯で春に獲れる巻貝。コリコリとした歯ごたえと磯の香り、ほろ苦い肝が珍味です。壺焼きや刺身にして、海女の里ならではの味を堪能できます。', '夏の「サザエ」と共通', 'images/chiba_sazae.png'),
('chiba', 'spring', 'いわし', '千葉沿岸で春に脂がのるイワシ。青魚特有の旨みと栄養が豊富です。刺身やつみれ、なめろうにして、新鮮なうちに味わいたい春の魚です。', '秋の「いわし」と共通', 'images/chiba_iwashi.png'),
('chiba', 'spring', '菜花のおひたし', '千葉名産の菜の花を使った春の家庭料理。ほろ苦さと爽やかな香りが、出汁と醤油でやさしくまとまります。春の訪れを感じる、彩り豊かな郷土の味です。', '', 'images/chiba_nabananoohitashi.png'),
('chiba', 'spring', 'びわゼリー', '千葉・房州びわを使った春のスイーツ。びわの上品な甘みと香りを、ぷるんとしたゼリーに閉じ込めています。産地ならではの、初夏を感じるデザートです。', '', 'images/chiba_biwazelly.png'),
('chiba', 'spring', '春レタス', '千葉で春に旬を迎えるレタス。葉が瑞々しくパリッとした食感で、ほのかな甘みがあります。サラダや炒め物で、春の爽やかさを味わえます。', '', 'images/chiba_haruretasu.png'),
('chiba', 'summer', 'スイカ', '千葉・富里は全国有数のスイカ産地。夏に旬を迎える果実は、シャリッとした食感とたっぷりの甘い果汁が自慢です。冷やして頬張る夏の風物詩です。', '', 'images/chiba_suika.png'),
('chiba', 'summer', '梨', '千葉は梨の生産量で全国上位を誇る名産地。夏から実る果実は、シャリッとした食感とあふれる果汁、すっきりした甘みが格別です。冷やして最適です。', '秋の「梨」と共通', 'images/chiba_nashi.png'),
('chiba', 'summer', 'とうもろこし', '千葉の畑で夏に実る甘味野菜。粒がはじけるような食感と強い甘さが特徴で、もぎたては生でも食べられるほど。茹でても焼いても絶品です。', '', 'images/chiba_toumorokoshi.png'),
('chiba', 'summer', '枝豆', '夏の食卓に欠かせない千葉産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/chiba_edamame.png'),
('chiba', 'summer', '伊勢えび', '千葉・外房で夏に獲れる高級海老。プリプリとした弾力ある身と濃厚な甘みが特徴です。刺身や味噌汁、姿焼きにして、磯の贅沢を堪能できます。', '', 'images/chiba_iseebi.png'),
('chiba', 'summer', 'トマト', '夏の日差しを浴びて千葉で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/chiba_tomato.png'),
('chiba', 'summer', 'かつお', '千葉沖を回遊する夏の青魚。さっぱりとした初がつおは、もちもちの身と爽やかな旨みが特徴です。刺身やたたき、なめろうで海の幸を楽しめます。', '', 'images/chiba_katsuo.png'),
('chiba', 'summer', 'サザエ', '千葉の磯で夏に獲れる巻貝。コリコリとした歯ごたえと磯の香り、ほろ苦い肝が珍味です。壺焼きや刺身にして、海辺の千葉らしい味を堪能できます。', '春の「サザエ」画像を使用', 'images/chiba_sazae.png'),
('chiba', 'summer', 'なす', '夏の千葉で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/chiba_nasu.png'),
('chiba', 'summer', 'きゅうり', '千葉の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/chiba_kyuri.png'),
('chiba', 'summer', 'オクラ', '夏の千葉で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/chiba_okura.png'),
('chiba', 'summer', 'ズッキーニ', '夏に千葉で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。ラタトゥイユやソテー、グリルで素材の旨みを引き出せます。', '', 'images/chiba_zucchini.png'),
('chiba', 'summer', 'ブルーベリー', '夏に千葉の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。そのまま食べるほかジャムやスイーツにも合います。', '', 'images/chiba_blueberry.png'),
('chiba', 'summer', 'びわ加工品', '千葉・房州びわを使った夏の保存食。びわの上品な甘みを生かしたジャムやシロップが人気です。産地ならではの、季節の恵みを長く楽しめる加工品です。', '', 'images/chiba_biwakakouhin.png'),
('chiba', 'summer', '冷やしなめろう', '千葉の郷土料理なめろうを冷たく仕立てた夏の味。新鮮なアジやイワシを薬味とともに叩き、さっぱりと味わえます。漁師町・千葉ならではの夏の一品です。', '', 'images/chiba_hiyashinamerou.png'),
('chiba', 'summer', '焼きとうもろこし', '千葉のとうもろこしを香ばしく焼いた夏の味。醤油の香りと甘い実が食欲をそそります。海辺の行楽や夏祭りでも親しまれる、季節を感じる一品です。', '', 'images/chiba_yakitoumorokoshi.png'),
('chiba', 'summer', '夏野菜', '千葉の温暖な気候が育む夏野菜の総称。なすやトマト、きゅうりなどが瑞々しく実ります。彩り豊かで栄養満点、夏の食卓を支える千葉自慢の野菜です。', '', 'images/chiba_natsuyasai.png'),
('chiba', 'summer', 'かき氷', '夏の千葉で涼を楽しむ定番スイーツ。ふんわり削った氷に蜜をかけ、暑さを癒します。海水浴帰りにも嬉しい、夏の風物詩として親しまれています。', '', 'images/chiba_kakigori.png'),
('chiba', 'autumn', '落花生', '千葉が全国生産の大半を占める特産品。秋に収穫される豆は、煎ると香ばしく濃厚な旨みが広がります。茹で落花生は産地ならではの旬の味わいです。', '', 'images/chiba_rakkasei.png'),
('chiba', 'autumn', '新米', '秋に収穫される千葉産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/chiba_shinmai.png'),
('chiba', 'autumn', 'さんま', '秋に千葉沖を回遊する旬の青魚。脂がのって身が締まり、塩焼きにすると香ばしさが格別です。秋の食卓を代表する庶民の魚として親しまれます。', '', 'images/chiba_sanma.png'),
('chiba', 'autumn', '栗', '秋の千葉を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/chiba_kuri.png'),
('chiba', 'autumn', 'さつまいも', '秋に収穫される千葉産のさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/chiba_satsumaimo.png'),
('chiba', 'autumn', 'なめろう', '千葉・房総の漁師に伝わる郷土料理。新鮮なアジやイワシを味噌や薬味とともに叩き、なめらかに仕上げます。秋の脂がのった魚で作ると格別の味です。', '', 'images/chiba_namerou.png'),
('chiba', 'autumn', 'いわし', '千葉沿岸で秋に脂がのるイワシ。青魚特有の旨みと栄養が豊富です。刺身やつみれ、蒲焼きにして、新鮮なうちに味わいたい秋の魚です。', '春の「いわし」画像を使用', 'images/chiba_iwashi.png'),
('chiba', 'autumn', 'きのこ', '秋に千葉の里山で採れるきのこ各種。香り高く歯ごたえがよく、自然の旨みが凝縮しています。鍋や汁物、炊き込みご飯で秋の恵みを味わえます。', '', 'images/chiba_kinoko.png'),
('chiba', 'autumn', '梨', '千葉で秋に実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として贈答にも喜ばれる、千葉自慢の果物です。', '既存の梨画像を使用', 'images/chiba_nashi.png'),
('chiba', 'autumn', '柿', '秋の千葉で色づく果実。とろりと甘い果肉とやさしい味わいが特徴で、そのまま食べるほか干し柿にも。秋の深まりを感じさせる季節の果物です。', '', 'images/chiba_kaki.png'),
('chiba', 'autumn', '秋なす', '秋に千葉で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/chiba_akinasu.png'),
('chiba', 'autumn', '里芋', '秋に収穫される千葉産の里芋。ねっとりとした独特の食感とやさしい甘みが持ち味です。煮っころがしや芋煮にすると、ほっとする秋の味わいになります。', '', 'images/chiba_satoimo.png'),
('chiba', 'autumn', '落花生味噌', '千葉名産の落花生を使った郷土の保存食。落花生の香ばしさと味噌の甘辛さが調和し、ご飯のお供にぴったりです。産地ならではの秋の味わいです。', '', 'images/chiba_rakkaseimiso.png'),
('chiba', 'autumn', '焼き芋', '千葉のさつまいもをじっくり焼き上げた秋の味。皮は香ばしく、中はとろりと甘く仕上がります。秋の深まりとともに恋しくなる、ほっとするおやつです。', '', 'images/chiba_yakiimo.png'),
('chiba', 'autumn', '栗ご飯', '秋の栗を米と炊き上げた千葉の季節料理。栗のほくほくとした甘みとご飯の旨みが調和します。実りの秋を感じさせる、家庭で親しまれる味です。', '', 'images/chiba_kurigohan.png'),
('chiba', 'autumn', '房総太巻き寿司', '千葉・房総に伝わる華やかな郷土寿司。切ると花や模様が現れる芸術的な巻き寿司で、祝い事に欠かせません。彩り豊かで、秋の行事を彩る伝統の味です。', '', 'images/chiba_bosofutomakizushi.png'),
('chiba', 'autumn', '秋サバ', '秋に千葉沖で脂がのるサバ。青魚特有の濃厚な旨みと栄養が豊富です。塩焼きや味噌煮、しめ鯖にして、脂ののった秋の海の幸を堪能できます。', '', 'images/chiba_akisaba.png'),
('chiba', 'autumn', 'ごぼう', '秋に旬を迎える千葉の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。きんぴらや煮物、汁物に加えると料理に滋味深いコクが生まれます。', '', 'images/chiba_gobou.png'),
('chiba', 'winter', 'はまぐり', '千葉の海で冬に旬を迎える二枚貝。身がふっくらと太り、上品な出汁の旨みが格別です。お吸い物や酒蒸し、焼きはまぐりで冬の磯の味を堪能できます。', '春の「ハマグリ」画像を使用', 'images/chiba_hamaguri.png'),
('chiba', 'winter', 'ほうれん草', '冬に甘みが濃くなる千葉の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/chiba_hourensou.png'),
('chiba', 'winter', 'ブリ', '冬に脂がのる千葉近海の出世魚。とろりとした濃厚な旨みが冬ならではです。刺身や照り焼き、ぶり大根にすると、寒い季節に身も心も温まります。', '', 'images/chiba_buri.png'),
('chiba', 'winter', '大根', '千葉は大根の名産地。冬は甘みを蓄えてみずみずしく、煮るととろける食感に。おでんやぶり大根、漬物に使え、冬の食卓を支える定番野菜です。', '', 'images/chiba_daikon.png'),
('chiba', 'winter', '鍋料理', '寒い千葉の冬に欠かせない郷土の鍋。新鮮な海の幸や地元の野菜が出汁に旨みを溶かします。漁師町ならではの、体を芯から温める冬のごちそうです。', '', 'images/chiba_nabelyouri.png'),
('chiba', 'winter', '鯖', '冬に千葉沖で脂がのるサバ。濃厚な旨みと栄養が豊富で、寒さで一層おいしくなります。塩焼きや味噌煮、しめ鯖にして、冬の海の幸を味わえます。', '', 'images/chiba_saba.png'),
('chiba', 'winter', '海苔', '千葉の海で冬に最盛期を迎える海産物。寒い時期の海苔は香り高く、口どけがよいのが特徴です。焼き海苔や巻き寿司で、磯の風味を存分に味わえます。', '春の「海苔」画像を使用', 'images/chiba_nori.png'),
('chiba', 'winter', '金目鯛', '千葉・房総沖で冬に旬を迎える高級魚。鮮やかな赤色と上品な脂、ふっくらした白身が特徴です。煮付けや刺身にして、冬のごちそうとして珍重されます。', '', 'images/chiba_kinmedai.png'),
('chiba', 'winter', '白菜', '冬の千葉で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/chiba_hakusai.png'),
('chiba', 'winter', '小松菜', '冬に旬を迎える千葉産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '', 'images/chiba_komatsuna.png'),
('chiba', 'winter', 'いわしつみれ', '千葉名産のイワシを使った冬の郷土料理。すり身を団子にして煮込むと、ふんわりとした食感と魚の旨みが汁に広がります。体を温める冬の味わいです。', '', 'images/chiba_iwashitsumire.png'),
('chiba', 'winter', 'なめろう茶漬け', '千葉の郷土料理なめろうを使った冬の食べ方。叩いた魚をご飯にのせ、温かい出汁をかけます。「さんが」とも通じる、漁師町ならではの滋味深い一杯です。', '', 'images/chiba_namerouchazuke.png'),
('chiba', 'winter', 'さんが焼き', '千葉・房総のなめろうを焼いた郷土料理。叩いた魚に薬味を混ぜて焼き上げ、香ばしさと旨みが凝縮します。冷めてもおいしい、漁師の知恵が生んだ味です。', '', 'images/chiba_sangayaki.png'),
('chiba', 'winter', 'おでん', '寒い千葉の冬に親しまれる煮込み料理。大根やこんにゃく、練り物が出汁を吸い込み、体を芯から温めます。家庭でも屋台でも愛される冬の定番です。', '', 'images/chiba_oden.png'),
('chiba', 'winter', '冬キャベツ', '冬の千葉で甘みを増す葉物。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '', 'images/chiba_fuyukyabetsu.png'),
('chiba', 'winter', 'ねぎ', '冬に旬を迎える千葉産のねぎ。加熱するととろりと甘くなり、香りも豊かです。鍋や汁物、薬味として冬の料理に深みと温かみを添えます。', '', 'images/chiba_negi.png'),
('chiba', 'winter', 'あさり汁', '千葉産のあさりを使った冬の汁物。あさりから出る濃厚な出汁の旨みが、寒い体を芯から温めます。磯の香り豊かな、漁師町らしいシンプルな一椀です。', '', 'images/chiba_asarijiru.png'),
('chiba', 'winter', '海鮮鍋', '千葉の新鮮な魚介を集めた冬の鍋。金目鯛やブリ、貝類などの旨みが出汁に溶け出し、贅沢な味わいに。海の幸豊かな千葉ならではのごちそうです。', '', 'images/chiba_kaisennabe.png'),
('tokyo', 'spring', '深川めし', '東京・深川に伝わる江戸の郷土料理。あさりやはまぐりをねぎとともに煮込み、ご飯にのせるか炊き込みます。下町情緒あふれる、春の磯の旨みが香る一品です。', '', 'images/tokyo_fukagawameshi.png'),
('tokyo', 'spring', '小松菜', '東京・江戸川区小松川が発祥の青菜。アクが少なく柔らかで、栄養価が高いのが特徴です。おひたしや炒め物、汁物にして、江戸由来の野菜を味わえます。', '冬の「小松菜」と共通', 'images/tokyo_komatsuna.png'),
('tokyo', 'spring', 'あさり', '東京湾の干潟で春に旬を迎える二枚貝。ふっくらとした身と濃厚な出汁の旨みが魅力です。味噌汁や深川めし、酒蒸しにして江戸前の味を楽しめます。', '', 'images/tokyo_asari.png'),
('tokyo', 'spring', '桜鍋', '東京で親しまれる馬肉の鍋料理。「桜肉」と呼ばれる馬肉を割り下で煮込み、甘みのある赤身と柔らかな食感が楽しめます。江戸から続く下町の味です。', '', 'images/tokyo_sakuranabe.png'),
('tokyo', 'spring', '山菜', '東京・奥多摩の山あいで春に芽吹く天然の味覚。ほろ苦さと独特の香りが春の到来を告げます。天ぷらやおひたしにして、季節限定の風味を楽しめます。', '', 'images/tokyo_sansai.png'),
('tokyo', 'spring', '東京うど', '東京・立川周辺で栽培される伝統野菜。地下で軟白栽培され、白く柔らかでシャキシャキとした食感が特徴です。酢の物や天ぷらで上品な香りを味わえます。', '', 'images/tokyo_tokyoudo.png'),
('tokyo', 'spring', 'いちご', '東京近郊で春に旬を迎える苺。観光農園での摘み取りも楽しめ、完熟の果実は甘酸っぱくジューシーです。都市近郊ならではの新鮮な春の果物です。', '', 'images/tokyo_ichigo.png'),
('tokyo', 'spring', 'くさや', '東京・伊豆諸島の伝統的な干物。独特の発酵臭と濃厚な旨みが特徴で、好む人を虜にします。あぶって食べると、島ならではの深い味わいが広がります。', '冬の「くさや」と共通', 'images/tokyo_kusaya.png'),
('tokyo', 'spring', '春キャベツ', '東京近郊で春に旬を迎えるキャベツ。葉がやわらかく巻きがゆるやかで、甘みが強いのが持ち味です。生のサラダや浅漬けで瑞々しさを楽しめます。', '', 'images/tokyo_harukyabetsu.png'),
('tokyo', 'spring', '春大根', '東京近郊で春に育つ大根。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '', 'images/tokyo_harudaikon.png'),
('tokyo', 'spring', '新玉ねぎ', '春に収穫される東京近郊の早採り玉ねぎ。水分が多く辛みが穏やかで、生でも甘く食べられます。スライスサラダや丸ごと蒸し料理で旬を楽しめます。', '', 'images/tokyo_shintamanegi.png'),
('tokyo', 'spring', '江戸前穴子', '東京湾で獲れる江戸前の穴子。春から脂がのり、ふっくらと柔らかな身が特徴です。天ぷらや煮穴子、寿司ネタにして、江戸前の伝統の味を堪能できます。', '', 'images/tokyo_edomaeanago.png'),
('tokyo', 'spring', '東京野菜', '東京近郊で育つ伝統野菜や地場野菜の総称。新鮮さが身上で、都市の食卓に彩りを添えます。江戸東京野菜として受け継がれる希少な品種もあります。', '', 'images/tokyo_tokyoyasai.png'),
('tokyo', 'spring', '桜餅', '春を代表する東京の和菓子。桜の葉で包んだ餅にあんこを入れ、葉の塩気と餅の甘みが調和します。花見の季節に欠かせない、江戸由来の春の銘菓です。', '', 'images/tokyo_sakuramochi.png'),
('tokyo', 'spring', 'よもぎ団子', '春のよもぎを練り込んだ東京の和菓子。草の爽やかな香りと団子のもちもち感が楽しめます。あんこやきな粉を添えて、春らしい風味を味わえます。', '', 'images/tokyo_yomogidango.png'),
('tokyo', 'spring', '春の天ぷら', '春の山菜や東京うどなどを揚げた季節の天ぷら。ほろ苦さと香りが、サクッとした衣に包まれて引き立ちます。旬の食材を楽しむ江戸前の調理法です。', '', 'images/tokyo_harunotenpura.png'),
('tokyo', 'spring', 'あさり汁', '東京湾産のあさりを使った春の汁物。あさりから出る濃厚な出汁の旨みが、やさしく体に染み渡ります。江戸前の磯の香りを楽しめるシンプルな一椀です。', '', 'images/tokyo_asarijiru.png'),
('tokyo', 'spring', '島しょ野菜', '東京の伊豆諸島・小笠原で育つ野菜の総称。温暖な気候と海風が育む独特の風味が魅力です。明日葉など、島ならではの個性的な野菜が知られています。', '', 'images/tokyo_shimashoyasai.png'),
('tokyo', 'summer', 'もんじゃ焼き', '東京・月島を代表する下町グルメ。ゆるい生地を鉄板で焼きながら食べる独特のスタイルで、香ばしいおこげが楽しめます。江戸の庶民に愛される味です。', '', 'images/tokyo_monjayaki.png'),
('tokyo', 'summer', '江戸前寿司', '東京湾の魚介を使った伝統的な握り寿司。新鮮なネタと熟練の技が生む、シンプルで奥深い味わいです。江戸で生まれた、東京を代表する食文化です。', '冬の「江戸前寿司」と共通', 'images/tokyo_edomaezushi.png'),
('tokyo', 'summer', '穴子', '東京湾で夏に旬を迎える江戸前の穴子。脂がのってふっくらと柔らかく、上品な甘みがあります。天ぷらや煮穴子、寿司ネタにして夏の江戸前を堪能できます。', '', 'images/tokyo_anago.png'),
('tokyo', 'summer', '枝豆', '夏の食卓に欠かせない東京近郊産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/tokyo_edamame.png'),
('tokyo', 'summer', 'トマト', '夏の日差しを浴びて東京近郊で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/tokyo_tomato.png'),
('tokyo', 'summer', 'ブルーベリー', '夏に東京近郊の農園で色づく小さな果実。甘酸っぱい味わいと豊富な栄養が魅力で、摘みたては格別。都市近郊での観光農園でも親しまれています。', '', 'images/tokyo_blueberry.png'),
('tokyo', 'summer', '冷やしそば', '東京の蕎麦文化を代表する夏の一品。冷たく締めたそばはコシが際立ち、つるりとした喉ごしが楽しめます。江戸前のそばつゆで暑い季節にぴったりです。', '', 'images/tokyo_hiyashisoba.png'),
('tokyo', 'summer', '江戸前天丼', '東京湾の海老や穴子を揚げてご飯にのせた江戸前の丼。甘辛いタレが染みた天ぷらとご飯の相性が抜群です。江戸から続く下町の名物料理です。', '', 'images/tokyo_edomaetendon.png'),
('tokyo', 'summer', 'きゅうり', '東京近郊の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/tokyo_kyuri.png'),
('tokyo', 'summer', 'なす', '夏の東京近郊で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/tokyo_nasu.png'),
('tokyo', 'summer', 'オクラ', '夏の東京近郊で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/tokyo_okura.png'),
('tokyo', 'summer', '島寿司', '東京・伊豆諸島に伝わる郷土寿司。醤油だれに漬けた白身魚をシャリにのせ、辛子を添えるのが特徴です。島ならではの工夫が生んだ、夏に映える寿司です。', '', 'images/tokyo_shimazushi.png'),
('tokyo', 'summer', 'ところてん', '夏の東京で親しまれる涼味。海藻から作られ、つるりとした喉ごしと爽やかさが暑さを和らげます。酢醤油や黒蜜で食べる、江戸から続く夏のおやつです。', '', 'images/tokyo_tokoroten.png'),
('tokyo', 'summer', 'かき氷', '夏の東京で涼を楽しむ定番スイーツ。ふんわり削った氷に蜜をかけ、暑さを癒します。downtown の甘味処から専門店まで、夏に欠かせない一品です。', '', 'images/tokyo_kakigori.png'),
('tokyo', 'summer', '冷やし小松菜', '東京伝統の小松菜を冷たく仕立てた夏の一品。さっと茹でて冷やすと、シャキッとした食感と爽やかさが引き立ちます。江戸由来の青菜を夏らしく味わえます。', '', 'images/tokyo_hiyashikomatsuna.png'),
('tokyo', 'summer', '夏野菜', '東京近郊で育つ夏野菜の総称。なすやトマト、きゅうりなどが瑞々しく実ります。都市近郊の新鮮さを生かし、夏の食卓を彩る彩り豊かな野菜です。', '', 'images/tokyo_natsuyasai.png'),
('tokyo', 'summer', '天ざるそば', '東京のそば文化を代表する夏の一品。冷たいざるそばに、海老や野菜の天ぷらを添えます。そばの喉ごしと天ぷらの香ばしさが楽しめる江戸前の味です。', '', 'images/tokyo_tenzarusoba.png'),
('tokyo', 'summer', '深川冷やし飯', '東京・深川めしを冷たく仕立てた夏の食べ方。あさりの旨みが染みたご飯を冷やし、さっぱりと味わえます。暑い季節に下町の味を楽しむ工夫の一品です。', '', 'images/tokyo_fukagawahiyashimeshi.png'),
('tokyo', 'autumn', '柳川鍋', '東京の下町に伝わる江戸前の鍋料理。どじょうとごぼうを卵でとじ、甘辛い割り下で煮込みます。滋養豊かで、秋に体を温める江戸の伝統料理です。', '', 'images/tokyo_yanagawanabe.png'),
('tokyo', 'autumn', '新そば', '秋に収穫したそばの実で打つ東京のそば。香りが高く、みずみずしい風味とコシのある食感が際立ちます。江戸前のそばつゆで味わう秋の味覚です。', '', 'images/tokyo_shinsoba.png'),
('tokyo', 'autumn', 'きのこ', '秋に東京・奥多摩の山で採れるきのこ各種。香り高く歯ごたえがよく、自然の旨みが凝縮しています。鍋や汁物、炊き込みご飯で秋の恵みを味わえます。', '', 'images/tokyo_kinoko.png'),
('tokyo', 'autumn', '栗', '秋の東京近郊を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、和菓子にして、実りの秋を存分に味わえます。', '', 'images/tokyo_kuri.png'),
('tokyo', 'autumn', '和菓子', '秋の風情を映した東京の伝統菓子。栗やさつまいもを使った季節限定の品が並びます。江戸から続く老舗の技が光る、目にも美しい秋の味覚です。', '', 'images/tokyo_wagashi.png'),
('tokyo', 'autumn', '東京X', '東京で開発されたブランド豚。きめ細かな肉質と甘くあっさりした脂、しっかりとした旨みが特徴です。しゃぶしゃぶや焼き物で上質な味わいを堪能できます。', '冬のしゃぶしゃぶと共通', 'images/tokyo_tokyox.png'),
('tokyo', 'autumn', 'さつまいも', '秋に東京近郊で収穫されるさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や芋ようかんにして、秋の甘みを堪能できます。', '', 'images/tokyo_satsumaimo.png'),
('tokyo', 'autumn', '梨', '東京近郊で秋に実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として親しまれる果物です。', '', 'images/tokyo_nashi.png'),
('tokyo', 'autumn', '秋なす', '秋に東京近郊で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/tokyo_akinasu.png'),
('tokyo', 'autumn', 'しいたけ', '秋に東京近郊で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/tokyo_shiitake.png'),
('tokyo', 'autumn', '新米', '秋に収穫される東京近郊の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/tokyo_shinmai.png'),
('tokyo', 'autumn', '江戸前天ぷら', '東京湾の魚介を使った江戸前の天ぷら。秋は脂ののった魚介を、サクッと軽い衣で揚げます。素材の旨みを引き出す、江戸で磨かれた調理技です。', '', 'images/tokyo_edomaetenpura.png'),
('tokyo', 'autumn', '栗ようかん', '秋の栗を使った東京の和菓子。なめらかなようかんに栗の甘みと食感が加わり、上品な味わいです。江戸から続く老舗の技が光る、秋の銘菓です。', '', 'images/tokyo_kuriyokan.png'),
('tokyo', 'autumn', '芋ようかん', '東京・浅草の名物和菓子。さつまいもの自然な甘みとしっとりした食感が魅力で、添加物に頼らない素朴な味わいです。下町を代表する秋の銘菓です。', '', 'images/tokyo_imoyokan.png'),
('tokyo', 'autumn', 'きのこそば', '秋のきのこをのせた東京のそば。きのこの香りと旨みが、コシのあるそばと出汁に溶け合います。江戸前のそば文化が生んだ、秋らしい温かな一杯です。', '', 'images/tokyo_kinokosoba.png'),
('tokyo', 'autumn', '秋刀魚', '秋に東京の市場に並ぶ旬の青魚。脂がのって身が締まり、塩焼きにすると香ばしさが格別です。目黒のさんま祭りでも知られる、秋の庶民の味です。', '', 'images/tokyo_sanma.png'),
('tokyo', 'autumn', 'ごぼう', '秋に旬を迎える東京近郊の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。柳川鍋やきんぴら、煮物に加えると料理に滋味深いコクが生まれます。', '', 'images/tokyo_gobou.png'),
('tokyo', 'autumn', '島しょ焼酎', '東京・伊豆諸島で造られる本格焼酎。麦や芋を原料に、島の風土が育む個性的な風味が特徴です。秋の味覚とともに楽しみたい、島ならではの地酒です。', '', 'images/tokyo_shimashoshochu.png'),
('tokyo', 'winter', 'おでん', '東京・関東炊きとして親しまれる冬の煮込み。濃いめの出汁に大根やちくわぶが染み込み、体を温めます。下町の屋台から家庭まで愛される江戸の味です。', '', 'images/tokyo_oden.png'),
('tokyo', 'winter', '小松菜', '冬に旬を迎える東京伝統の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、雑煮にして、江戸由来の野菜を冬に味わえます。', '春の小松菜画像を使用', 'images/tokyo_komatsuna.png'),
('tokyo', 'winter', '海苔', '東京湾で育つ冬の海産物。寒い時期の海苔は香り高く、口どけがよいのが特徴です。焼き海苔や巻き寿司にして、江戸前の磯の風味を存分に味わえます。', '', 'images/tokyo_nori.png'),
('tokyo', 'winter', 'ちゃんこ鍋', '東京・両国の相撲文化が生んだ鍋料理。肉や魚、野菜をたっぷり煮込み、滋養豊かで食べ応えがあります。寒い冬に体を温める、力士直伝の味です。', '', 'images/tokyo_chankonabe.png'),
('tokyo', 'winter', 'ブリ', '冬に脂がのる東京近海の出世魚。とろりとした濃厚な旨みが冬ならではです。刺身や照り焼き、ぶり大根にすると、寒い季節に身も心も温まります。', '', 'images/tokyo_buri.png'),
('tokyo', 'winter', '大根', '冬の東京近郊で甘みを蓄える根菜。みずみずしくやわらかで、煮るととろける食感に。おでんやぶり大根に使え、江戸の冬の食卓を支える定番野菜です。', '', 'images/tokyo_daikon.png'),
('tokyo', 'winter', '甘酒', '寒い東京の冬に親しまれる発酵飲料。米麹の自然な甘みと優しい温かさが、冷えた体を芯から温めます。初詣や寒い夜に欠かせない、江戸からの冬の味です。', '', 'images/tokyo_amazake.png'),
('tokyo', 'winter', '江戸前寿司', '東京湾の冬の魚介を使った握り寿司。寒ブリや金目鯛など脂ののったネタが楽しめます。熟練の技が光る、東京を代表する冬の食文化です。', '夏の寿司画像を使用', 'images/tokyo_edomaezushi.png'),
('tokyo', 'winter', '深川鍋', '東京・深川に伝わるあさりの鍋料理。新鮮なあさりとねぎを味噌仕立てで煮込み、磯の旨みが体を温めます。下町情緒あふれる、冬の郷土鍋です。', '', 'images/tokyo_fukagawanabe.png'),
('tokyo', 'winter', 'ねぎ', '冬に旬を迎える東京近郊のねぎ。加熱するととろりと甘くなり、香りも豊かです。鍋や汁物、薬味として冬の料理に深みと温かみを添えます。', '', 'images/tokyo_negi.png'),
('tokyo', 'winter', '白菜', '冬の東京近郊で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/tokyo_hakusai.png'),
('tokyo', 'winter', 'ほうれん草', '冬に甘みが濃くなる東京近郊の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/tokyo_hourensou.png'),
('tokyo', 'winter', '湯豆腐', '東京の冬に親しまれる温かい豆腐料理。なめらかな豆腐を出汁で温め、大豆本来の甘みを味わいます。体に優しく、寒い夜にほっとする一品です。', '', 'images/tokyo_yudofu.png'),
('tokyo', 'winter', '冬そば', '寒い時期に味わう東京の温かいそば。出汁の効いたつゆとコシのあるそばが、冷えた体を温めます。江戸前のそば文化が育んだ、冬に恋しい一杯です。', '', 'images/tokyo_fuyusoba.png'),
('tokyo', 'winter', 'あさり鍋', '東京湾産のあさりを使った冬の鍋。あさりから出る濃厚な出汁の旨みが、野菜や豆腐に染み込みます。江戸前の磯の味を楽しむ、温かな冬の郷土鍋です。', '', 'images/tokyo_asarinabe.png'),
('tokyo', 'winter', 'くさや', '東京・伊豆諸島の伝統的な干物。独特の発酵臭と濃厚な旨みが特徴で、冬の酒の肴に重宝されます。あぶって食べると、島ならではの深い味わいが広がります。', '春のくさや画像を使用', 'images/tokyo_kusaya.png'),
('tokyo', 'winter', '東京Xしゃぶしゃぶ', '東京のブランド豚・東京Xをしゃぶしゃぶで味わう一品。甘くあっさりした脂と柔らかな肉が、さっと火を通すことで引き立ちます。冬に嬉しいごちそうです。', '', 'images/tokyo_tokyoxshabushabu.png'),
('tokyo', 'winter', '小松菜鍋', '東京伝統の小松菜を主役にした冬の鍋。霜で甘みを増した小松菜の旨みが出汁に溶け出します。江戸由来の青菜を、温かく味わう冬の郷土鍋です。', '', 'images/tokyo_komatsunanabe.png'),
('kanagawa', 'spring', 'しらす', '神奈川・湘南を代表する春の海の幸。相模湾で水揚げされるイワシの稚魚で、釜揚げや生しらすとして味わえます。湘南名物として全国的に知られています。', '生しらす、しらす丼等と共通', 'images/kanagawa_shirasu.png'),
('kanagawa', 'spring', '湘南ゴールド', '神奈川が開発した黄金色の柑橘。爽やかな香りと甘酸っぱい味わいが特徴で、春に旬を迎えます。そのまま食べるほかスイーツにも使う、神奈川自慢の果物です。', '', 'images/kanagawa_shonangold.png'),
('kanagawa', 'spring', 'わかさぎ (わかめ)', '神奈川の沿岸で春に旬を迎える海藻。採れたては香り高く、しゃきしゃきとした歯ごたえが楽しめます。味噌汁や酢の物、しゃぶしゃぶで磯の味を味わえます。', 'data.jsの「わかめ」に対応', 'images/kanagawa_wakame.png'),
('kanagawa', 'spring', 'たけのこ', '神奈川の里山で春に掘られる旬の味覚。えぐみが少なくシャキッとした歯ざわりが魅力です。煮物や天ぷら、炊き込みご飯で春の香りを楽しめます。', '', 'images/kanagawa_takenoko.png'),
('kanagawa', 'spring', '鯵', '神奈川の相模湾で春に旬を迎える青魚。脂がのって身が締まり、上品な旨みがあります。刺身やたたき、塩焼きにして、新鮮な海の幸を堪能できます。', '', 'images/kanagawa_aji.png'),
('kanagawa', 'spring', 'サザエ', '神奈川の磯で春に獲れる巻貝。コリコリとした歯ごたえと磯の香り、ほろ苦い肝が珍味です。壺焼きや刺身にして、海辺の神奈川らしい味を堪能できます。', '夏の「サザエ」と共通', 'images/kanagawa_sazae.png'),
('kanagawa', 'spring', '建長汁', '神奈川・鎌倉の建長寺発祥とされる精進汁。崩した豆腐と根菜を煮込み、優しい味わいが特徴です。けんちん汁の語源とも言われる、由緒ある郷土の味です。', '冬のけんちん汁と共通', 'images/kanagawa_kenchinjiru.png'),
('kanagawa', 'spring', '春キャベツ', '神奈川・三浦は全国有数のキャベツ産地。春採りは葉がやわらかく甘みが強いのが持ち味です。生のサラダや浅漬けで、三浦野菜の瑞々しさを楽しめます。', '冬キャベツと共通', 'images/kanagawa_kyabetsu.png'),
('kanagawa', 'spring', '生しらす', '神奈川・湘南で春に味わえる旬の珍味。水揚げされたばかりの透明なしらすは、ぷりぷりの食感とほのかな甘みが格別です。鮮度が命の湘南名物です。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'spring', '春大根', '神奈川・三浦の名産大根の春採り。みずみずしく辛みが穏やかで、生でも食べやすい甘さがあります。サラダや浅漬け、煮物に幅広く使えます。', '大根、三浦大根と共通', 'images/kanagawa_daikon.png'),
('kanagawa', 'spring', '菜の花', '早春の畑を黄色く彩る神奈川の春野菜。ほろ苦さと独特の香りが特徴で、おひたしや辛子和えで季節感が引き立ちます。栄養価の高い緑黄色野菜です。', '', 'images/kanagawa_nanohana.png'),
('kanagawa', 'spring', '新玉ねぎ', '神奈川・三浦の特産。春に収穫される早採り玉ねぎは、水分が多く辛みが穏やかで生でも甘く食べられます。スライスサラダで三浦の味を楽しめます。', '', 'images/kanagawa_shintamanegi.png'),
('kanagawa', 'spring', '鎌倉野菜', '神奈川・鎌倉の畑で育つ多彩な地場野菜。色とりどりの西洋野菜や伝統野菜が揃い、新鮮さと個性的な味わいが魅力です。レストランでも人気の食材です。', '湘南・三浦野菜、秋鎌倉と共通', 'images/kanagawa_yasai.png'),
('kanagawa', 'spring', '小田原かまぼこ', '神奈川・小田原を代表する練り物。新鮮な白身魚を使い、弾力ある食感と上品な甘みが特徴です。職人技が光る、小田原の伝統が育んだ名産品です。', '冬のかまぼこと共通', 'images/kanagawa_kamaboko.png'),
('kanagawa', 'spring', '桜えび風かき揚げ', '神奈川の春に楽しむ海の幸のかき揚げ。小さな海老を衣でまとめて揚げ、香ばしさとサクサク感が楽しめます。相模湾の恵みを味わう春の一品です。', '', 'images/kanagawa_sakuraebifu_kakiage.png'),
('kanagawa', 'spring', '湘南しらす丼', '神奈川・湘南名物のしらすをご飯にのせた丼。釜揚げや生しらすをたっぷりのせ、磯の香りと甘みが楽しめます。海辺の街・湘南を代表する春の味です。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'spring', 'よもぎ餅', '春に摘んだよもぎを練り込んだ神奈川の郷土菓子。草の爽やかな香りと餅の柔らかさが調和します。あんことの相性も良く、春の行事に欠かせない味です。', '', 'images/kanagawa_yomogimochi.png'),
('kanagawa', 'spring', '三浦春野菜', '神奈川・三浦半島で春に育つ野菜の総称。温暖な気候と海風が育む春キャベツや大根などが瑞々しく実ります。三浦ブランドとして親しまれる春の味です。', '既存の野菜画像を使用', 'images/kanagawa_yasai.png'),
('kanagawa', 'summer', '三崎マグロ', '神奈川・三崎港で水揚げされる遠洋マグロ。とろりとした脂と濃厚な旨みが特徴で、全国に知られる名産です。刺身や漬け丼で、三崎の味を堪能できます。', '冬のマグロ鍋と共通', 'images/kanagawa_maguro.png'),
('kanagawa', 'summer', 'トマト', '夏の日差しを浴びて神奈川で実るトマト。酸味と甘みのバランスがよく、ジューシーで旨みが濃いのが特徴です。冷やしてサラダや冷製料理に最適です。', '', 'images/kanagawa_tomato.png'),
('kanagawa', 'summer', '枝豆', '夏の食卓に欠かせない神奈川産の豆。ぷりっとした食感と濃い豆の旨みがあり、塩茹でがおすすめ。冷たい飲み物との相性も抜群の夏の定番です。', '', 'images/kanagawa_edamame.png'),
('kanagawa', 'summer', 'きゅうり', '神奈川の夏を代表する瑞々しい野菜。パリッとした歯ざわりと爽やかさで、暑い日の水分補給にも。漬物や酢の物、冷やし料理で活躍します。', '', 'images/kanagawa_kyuri.png'),
('kanagawa', 'summer', 'スイカ', '夏の神奈川を代表する果物。シャリッとした食感とたっぷりの水分、上品な甘みが暑さを癒します。冷やして頬張る瞬間はまさに夏の風物詩です。', '', 'images/kanagawa_suika.png'),
('kanagawa', 'summer', 'しらす丼', '神奈川・湘南名物のしらすをご飯にのせた夏の丼。釜揚げや生しらすの甘みと磯の香りが楽しめます。海水浴帰りにも嬉しい、湘南を代表する味です。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'summer', '生しらす', '神奈川・湘南で夏にも味わえる旬の珍味。透明でぷりぷりとした食感とほのかな甘みが格別です。鮮度が命のため、産地ならではの贅沢な一品です。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'summer', 'かき氷', '夏の神奈川で涼を楽しむ定番スイーツ。ふんわり削った氷に蜜をかけ、暑さを癒します。海辺の街や鎌倉の甘味処でも親しまれる夏の風物詩です。', '', 'images/kanagawa_kakigori.png'),
('kanagawa', 'summer', 'なす', '夏の神奈川で旬を迎える野菜。皮はつややかで身はとろりと柔らかく、油との相性が抜群です。焼きナスや揚げ浸し、炒め物で夏の食卓を彩ります。', '', 'images/kanagawa_nasu.png'),
('kanagawa', 'summer', 'オクラ', '夏の神奈川で旬を迎えるネバネバ野菜。独特の粘りと栄養が夏の体に嬉しい一品です。さっと茹でて和え物や冷やし料理に加えると食欲が進みます。', '', 'images/kanagawa_okura.png'),
('kanagawa', 'summer', 'ズッキーニ', '夏に神奈川で収穫される洋風野菜。淡白でクセがなく、加熱するととろける食感に。鎌倉野菜としても親しまれ、ソテーやグリルで楽しめます。', '', 'images/kanagawa_zucchini.png'),
('kanagawa', 'summer', 'サザエ', '神奈川の磯で夏に獲れる巻貝。コリコリとした歯ごたえと磯の香り、ほろ苦い肝が珍味です。壺焼きや刺身にして、海辺の神奈川らしい味を堪能できます。', '春の「サザエ」画像を使用', 'images/kanagawa_sazae.png'),
('kanagawa', 'summer', 'アジフライ', '神奈川名物の鯵を使った夏の揚げ物。新鮮な鯵に衣をつけて揚げると、ふっくらした身とサクサクの衣が好相性です。相模湾の恵みを味わう定番料理です。', '', 'images/kanagawa_ajifurai.png'),
('kanagawa', 'summer', '冷やし海鮮丼', '神奈川の新鮮な魚介を冷たいご飯にのせた夏の丼。マグロやしらす、鯵などの旨みが楽しめます。暑い季節にさっぱり味わえる、海辺の街らしい一品です。', '', 'images/kanagawa_hiyashikaisendon.png'),
('kanagawa', 'summer', '湘南野菜', '神奈川・湘南地域で育つ地場野菜の総称。温暖な気候と海風が育み、瑞々しく彩り豊かです。新鮮さが身上で、地元レストランでも重宝される夏の味です。', '既存の野菜画像を使用', 'images/kanagawa_yasai.png'),
('kanagawa', 'summer', '夏みかん加工品', '神奈川の温暖な地で育つ夏みかんの加工品。爽やかな酸味と苦みを生かしたマーマレードやゼリーが人気です。柑橘の香り豊かな、夏の保存食です。', '', 'images/kanagawa_natsumikankakouhin.png'),
('kanagawa', 'summer', 'とうもろこし', '神奈川の畑で夏に実る甘味野菜。粒がはじけるような食感と強い甘さが特徴で、もぎたては生でも食べられるほど。茹でても焼いても絶品です。', '', 'images/kanagawa_toumorokoshi.png'),
('kanagawa', 'summer', '三浦夏野菜', '神奈川・三浦半島で夏に育つ野菜の総称。温暖な気候と海風が育むなすやトマトなどが瑞々しく実ります。三浦ブランドとして親しまれる夏の味です。', '既存の野菜画像を使用', 'images/kanagawa_yasai.png'),
('kanagawa', 'autumn', '三浦大根', '神奈川・三浦半島の伝統的な大根。中央がふくらんだ独特の形で、きめ細かくやわらかな肉質と上品な甘みが特徴です。煮物にすると味がよく染みます。', '既存の大根画像を使用', 'images/kanagawa_daikon.png'),
('kanagawa', 'autumn', '梨', '神奈川で秋に実る梨。みずみずしい果汁とすっきりした甘さ、シャリッとした食感が魅力です。秋の味覚として親しまれる果物です。', '', 'images/kanagawa_nashi.png'),
('kanagawa', 'autumn', 'さつまいも', '秋に収穫される神奈川産のさつまいも。しっとり甘くホクホクとした食感が魅力です。焼き芋や天ぷら、スイートポテトで秋の甘みを堪能できます。', '', 'images/kanagawa_satsumaimo.png'),
('kanagawa', 'autumn', '牛鍋', '神奈川・横浜が発祥とされる文明開化の鍋料理。牛肉を割り下で煮込み、甘辛い味わいと柔らかな肉が楽しめます。すき焼きの原型ともいわれる横浜の味です。', '', 'images/kanagawa_gyunabe.png'),
('kanagawa', 'autumn', 'サンマ', '秋に神奈川沖を回遊する旬の青魚。脂がのって身が締まり、塩焼きにすると香ばしさが格別です。秋の食卓を代表する庶民の魚として親しまれます。', '', 'images/kanagawa_sanma.png'),
('kanagawa', 'autumn', '栗', '秋の神奈川を代表する味覚。大粒でほくほくとした食感と上品な甘みが特徴です。栗ご飯や甘露煮、焼き栗にして、実りの秋を存分に味わえます。', '', 'images/kanagawa_kuri.png'),
('kanagawa', 'autumn', 'しめじ', '秋に神奈川で旬を迎えるきのこ。プリッとした歯ごたえと上品な旨みが特徴で、クセがなく使いやすいのが魅力です。炒め物や鍋、汁物で活躍します。', '', 'images/kanagawa_shimeji.png'),
('kanagawa', 'autumn', '鎌倉野菜', '神奈川・鎌倉の畑で秋に育つ多彩な地場野菜。色とりどりの西洋野菜や伝統野菜が揃い、秋ならではの根菜も豊富です。レストランでも人気の食材です。', '既存の野菜画像を使用', 'images/kanagawa_yasai.png'),
('kanagawa', 'autumn', '秋なす', '秋に神奈川で実る引き締まったナス。夏のものより皮が薄く身が締まり、甘みが増します。焼きナスや田楽、煮浸しで秋ならではの味わいを楽しめます。', '', 'images/kanagawa_akinasu.png'),
('kanagawa', 'autumn', '新米', '秋に収穫される神奈川産の新米。炊きたては艶やかでもっちりとし、噛むほどに甘みが広がります。一年で最も米のおいしさを感じられる季節の恵みです。', '', 'images/kanagawa_shinmai.png'),
('kanagawa', 'autumn', 'しいたけ', '秋に神奈川で旬を迎えるきのこ。肉厚で香り高く、噛むと旨みが広がります。焼き物や煮物、鍋の具として和食に欠かせない秋の味覚です。', '', 'images/kanagawa_shiitake.png'),
('kanagawa', 'autumn', 'ごぼう', '秋に旬を迎える神奈川の根菜。豊かな香りと歯ごたえ、独特の風味が特徴です。きんぴらや煮物、汁物に加えると料理に滋味深いコクが生まれます。', '', 'images/kanagawa_gobou.png'),
('kanagawa', 'autumn', '芋ようかん', '神奈川産のさつまいもで作る秋の和菓子。芋本来の自然な甘みとしっとりした食感が魅力です。素朴ながら奥深い、秋にうれしい和菓子です。', '', 'images/kanagawa_imoyokan.png'),
('kanagawa', 'autumn', '栗ご飯', '秋の栗を米と炊き上げた神奈川の季節料理。栗のほくほくとした甘みとご飯の旨みが調和します。実りの秋を感じさせる、家庭で親しまれる味です。', '', 'images/kanagawa_kurigohan.png'),
('kanagawa', 'autumn', '小田原干物', '神奈川・小田原の伝統的な干物。新鮮な魚を干し上げ、旨みが凝縮した深い味わいが特徴です。あぶって食べると、相模湾の恵みを堪能できる名産品です。', '', 'images/kanagawa_odawarahimono.png'),
('kanagawa', 'autumn', 'きのこ汁', '秋に採れる複数のきのこを使った神奈川の郷土汁。きのこの旨みが溶け出した出汁が体を温めます。山の恵みを存分に味わえる秋ならではの一椀です。', '', 'images/kanagawa_kinokojiru.png'),
('kanagawa', 'autumn', '湘南ポーク', '神奈川・湘南地域で育てられるブランド豚。きめ細かな肉質と甘みのある脂、しっかりとした旨みが特徴です。焼き物やしゃぶしゃぶで上質な味を楽しめます。', '', 'images/kanagawa_shonanpork.png'),
('kanagawa', 'autumn', '秋しらす', '神奈川・湘南で秋にも水揚げされるしらす。秋のものは脂がのり、ふっくらとした食感と濃い旨みが楽しめます。釜揚げや丼で、湘南の味を堪能できます。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'winter', 'かまぼこ', '神奈川・小田原を代表する冬の練り物。新鮮な白身魚を使い、弾力ある食感と上品な甘みが特徴です。正月のおせちにも欠かせない、小田原の名産品です。', '既存のかまぼこ画像を使用', 'images/kanagawa_kamaboko.png'),
('kanagawa', 'winter', '鍋料理', '寒い神奈川の冬に欠かせない郷土の鍋。三崎マグロや三浦野菜など地元の食材が出汁に旨みを溶かします。海と畑の幸が揃う、体を温める冬のごちそうです。', '', 'images/kanagawa_nabelyouri.png'),
('kanagawa', 'winter', 'ブリ', '冬に脂がのる神奈川近海の出世魚。とろりとした濃厚な旨みが冬ならではです。刺身や照り焼き、ぶり大根にすると、寒い季節に身も心も温まります。', '', 'images/kanagawa_buri.png'),
('kanagawa', 'winter', '大根', '神奈川・三浦の名産大根。冬は甘みを蓄えてみずみずしく、煮るととろける食感に。おでんやぶり大根、漬物に使え、冬の食卓を支える定番野菜です。', '既存の大根画像を使用', 'images/kanagawa_daikon.png'),
('kanagawa', 'winter', '湘南しらす', '神奈川・湘南名物のしらす。冬の釜揚げしらすはふっくらと旨みが濃く、温かいご飯によく合います。一年を通じて愛される、湘南を代表する海の幸です。', '既存のしらす画像を使用', 'images/kanagawa_shirasu.png'),
('kanagawa', 'winter', '海鮮丼', '神奈川の新鮮な魚介を冬のご飯にのせた丼。三崎マグロやブリ、しらすなど旬の魚が楽しめます。海の幸豊かな神奈川ならではの、贅沢な一杯です。', '', 'images/kanagawa_kaisendon.png'),
('kanagawa', 'winter', '厚木シロコロ', '神奈川・厚木のご当地グルメ。豚の大腸を丸い形に焼いたホルモンで、外は香ばしく中はもちもちの食感です。寒い冬に人気の、厚木名物の一品です。', '', 'images/kanagawa_atsugishirokoro.png'),
('kanagawa', 'winter', '白菜', '冬の神奈川で甘みを増す葉物野菜。霜にあたることで柔らかく甘くなり、鍋物に最適です。漬物や煮物にも使え、冬に欠かせない万能野菜です。', '', 'images/kanagawa_hakusai.png'),
('kanagawa', 'winter', '三浦大根', '神奈川・三浦半島の伝統大根。冬に旬を迎え、きめ細かくやわらかな肉質と上品な甘みが際立ちます。煮物にすると味がよく染み、冬のごちそうになります。', '既存の大根画像を使用', 'images/kanagawa_daikon.png'),
('kanagawa', 'winter', '小松菜', '冬に旬を迎える神奈川産の青菜。霜にあたると甘みが増し、栄養価も高まります。おひたしや炒め物、汁物に使え、寒い時期の食卓に彩りを添えます。', '', 'images/kanagawa_komatsuna.png'),
('kanagawa', 'winter', 'ほうれん草', '冬に甘みが濃くなる神奈川の葉物野菜。寒締め栽培で糖度が上がり、味が濃厚になります。おひたしやソテー、鍋の具として冬の栄養源になります。', '', 'images/kanagawa_hourensou.png'),
('kanagawa', 'winter', '湯豆腐', '神奈川の冬に親しまれる温かい豆腐料理。なめらかな豆腐を出汁で温め、大豆本来の甘みを味わいます。体に優しく、寒い夜にほっとする一品です。', '', 'images/kanagawa_yudofu.png'),
('kanagawa', 'winter', 'けんちん汁', '神奈川・鎌倉の建長寺に由来する根菜たっぷりの精進汁。大根やごぼう、里芋などを煮込み、優しい味わいが体を温めます。冬に親しまれる郷土の味です。', '春の「建長汁」画像を使用', 'images/kanagawa_kenchinjiru.png'),
('kanagawa', 'winter', '三崎マグロ鍋', '神奈川・三崎港のマグロを使った冬の鍋。マグロのあらや身を野菜とともに煮込み、濃厚な旨みが出汁に溶け出します。漁港の街ならではのごちそうです。', '既存のマグロ画像を使用', 'images/kanagawa_maguro.png'),
('kanagawa', 'winter', 'おでん', '寒い神奈川の冬に親しまれる煮込み料理。大根やこんにゃく、小田原の練り物が出汁を吸い込み、体を芯から温めます。家庭でも屋台でも愛される定番です。', '', 'images/kanagawa_oden.png'),
('kanagawa', 'winter', '金目鯛', '神奈川・相模湾で冬に旬を迎える高級魚。鮮やかな赤色と上品な脂、ふっくらした白身が特徴です。煮付けや刺身にして、冬のごちそうとして珍重されます。', '', 'images/kanagawa_kinmedai.png'),
('kanagawa', 'winter', '冬キャベツ', '神奈川・三浦の冬キャベツ。葉が固く締まり、加熱するととろりと甘くなります。煮込みやロールキャベツ、鍋物で、寒い季節においしさが際立ちます。', '既存のキャベツ画像を使用', 'images/kanagawa_kyabetsu.png'),
('kanagawa', 'winter', '海鮮鍋', '神奈川の新鮮な魚介を集めた冬の鍋。三崎マグロや金目鯛、貝類などの旨みが出汁に溶け出し、贅沢な味わいに。海の幸豊かな神奈川ならではのごちそうです。', '', 'images/kanagawa_kaisennabe.png');
